-- Round two of the makers' own tasting notes (2026-10-13), from each importer's `tasting_notes` capture via scripts/bourbon_notes.py emit; same shape and rule as 20261013_maker_tasting_notes.sql.
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "d19ac415-0e0e-4caf-b78a-28b7198a797c", "source": "angelsenvy.com", "source_url": "https://www.angelsenvy.com/us/en/whiskeys/bottled-in-bond/cask-strength-bottled-in-bond/", "reviewer": "Angel's Envy", "text": "Nose: Lightly caramelized sugars, vanilla wafers with a hint of banana pudding. Palate: Sweet and balanced. Honey latte. Light fruit syrup and toasted oak. Finish: Rounded and soft. Gently fades, begging for a second sip."}, {"product_id": "78326706-3a65-4511-a429-943f4024c72a", "source": "angelsenvy.com", "source_url": "https://www.angelsenvy.com/us/en/whiskeys/cask-strength/10-cask-rye/", "reviewer": "Angel's Envy", "text": "Nose: Warm aromas of medjool date, buttery brown sugar, and vanilla bean reduction. Palate: Candied ginger and rye spice meet the richness of rum-soaked pound cake. Velvety texture with a subtle touch of mint. Finish: Layers of molasses and grassy sugarcane give way to juicy tropical fruits and silky old oak tannins."}, {"product_id": "165fd711-3437-4a39-9f11-7bd5c5b447fa", "source": "angelsenvy.com", "source_url": "https://www.angelsenvy.com/us/en/whiskeys/cask-strength/12th-edition-cask-strength-rye/", "reviewer": "Angel's Envy", "text": "Nose: Creme brûlée with a hint of orange zest. Ripe honeycrisp apple and buckwheat. Palate: Honeyed pears, with rye spices, nutmeg, and well-integrated oak. Sweet cream and caramelized sugar. Finish: Fruity cream soda and floral blanc vermouth. Sweet spices slowly fade into pleasant notes of black tea and leather."}, {"product_id": "6a889f7e-332b-4637-894a-af5cbc4eb9a8", "source": "angelsenvy.com", "source_url": "https://www.angelsenvy.com/us/en/whiskeys/cask-strength/14th-edition-cask-10/", "reviewer": "Angel's Envy", "text": "Nose: Sweet cinnamon toast and creamy fruit nougat, woven over a backbone of candied nuts. Palate: Rich notes of baklava fade into ripe apricot, crème brulee, and cognac, spiced with a touch of grains of paradise. Finish: The port cask influence builds gracefully, revealing notes of rum raisin cake while leaving a lingering invitation for another sip."}, {"product_id": "a8de9a92-cd24-4231-b569-d37e546d4321", "source": "angelsenvy.com", "source_url": "https://www.angelsenvy.com/us/en/whiskeys/cellar-collection/2025-anejo-cask-finish/", "reviewer": "Angel's Envy", "text": "Nose: Floral and fruit-forward. Toasty vanilla, with a subtle clove smokiness. Palate: Baking spices and cracked pepper, tempered by herbal agave syrup. Earthy tobacco and brown sugar. Finish: Soft and balanced, with orange blossom honey, tropical fruits, and a French oak finish."}, {"product_id": "8f79a93d-8ace-45d0-a6cf-1ff988d3220e", "source": "angelsenvy.com", "source_url": "https://www.angelsenvy.com/us/en/whiskeys/signature-series/triple-oak-bourbon/", "reviewer": "Angel's Envy", "text": "Nose: Fresh, ripe apricot balanced by rich toasted oak, with highlights of honeysuckle blossom. Palate: Bold baking spices from the oak with subtle hints of brioche and vanilla custard. Top notes of red plum anchored by fresh tobacco and leather tannins. Finish: A pleasant spice, lingering notes of nutmeg, black pepper, and cardamom, with a refined sweetness of brown sugar, and molasses."}, {"product_id": "674a81ac-2fd6-45ba-8f75-acdbda582e11", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/sequential-4th-use-barrels/", "reviewer": "A. Smith Bowman", "text": "The result is a finished bourbon with notes of dried fruit, figs and vanilla with a peppery finish."}, {"product_id": "f04374c9-ff0a-49ba-94f3-664bbdcebf3e", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/abraham-hungarian-oak-lottery-2025/", "reviewer": "A. Smith Bowman", "text": "On the nose, the aroma of candied apricot engulfs your glass, unfolding layers of warm honey apples and a pronounced smokey dark chocolate on the palate. The finish lingers on the sides of your tongue with notes of dried fruit and char."}, {"product_id": "52049ef6-5f99-44cb-b52b-9ffd7415f639", "source": "asmithbowman.com", "source_url": "https://asmithbowman.com/abraham-rye-lottery-2026/", "reviewer": "A. Smith Bowman", "text": "On the nose, this limited-edition rye whiskey opens with rich notes of maple syrup layered with hints of copper and fresh Spring aromatics. The palate unfolds with flavors of vanilla, apricot and bright orange zest, balanced by subtle earthy undertones. It finishes spice-forward, highlighted by black pepper and a delicate hint of mint for a clean, lingering close."}, {"product_id": "152efb3c-c6b5-4bb1-9e61-d99425d4225b", "source": "backbonebourbon.com", "source_url": "https://backbonebourbon.com/backbone-bourbon-prime/", "reviewer": "Backbone Bourbon", "text": "Notes of caramel, oak, and dark cherry hit the nose. The palate starts off with sweet vanilla flavors quickly moving to a bold spice and finishes with a smooth, almost maple sweetness."}, {"product_id": "3f88e1c2-fa26-41ed-a7db-46ccd6876efe", "source": "backbonebourbon.com", "source_url": "https://backbonebourbon.com/old-bones-rye-10-year-reserve/", "reviewer": "Backbone Bourbon", "text": "A delightful aroma of orange peel and a subtle hint of vanilla on the nose. On the front of the palate, there is a touch of peppery cool mint that blossoms into a sweet honey flavor in the midpalate. The sweetness of the honey develops into a delicious butterscotch toffee that is carried through the long-lasting finish."}, {"product_id": "64aeb5ec-8bfc-4d11-b40d-04438b3082f1", "source": "backbonebourbon.com", "source_url": "https://backbonebourbon.com/bone-snapper-straight-rye-whiskey/", "reviewer": "Backbone Bourbon", "text": "On the nose are notes of cinnamon, rye bread, and leather. Spice from the rye is present up front with notes of anise and more subtle spices of orange peel and marmalade. This whisky has a bold finish that provides a wonderful zing and a comforting warmth all through your body."}, {"product_id": "051e2aa8-4605-45c1-ab27-db79c02a7823", "source": "backbonebourbon.com", "source_url": "https://backbonebourbon.com/bone-snapper-xray-4-year-reserve/", "reviewer": "Backbone Bourbon", "text": "On the nose are notes of pine tree and cinnamon. The first sip gets a decent amount of honey and caramel with hints of peppery spice coming through on a long but smooth finish. If you close your eyes and concen-trate, you might taste a little spearmint and eucalyptus in the mid-palate giving this whiskey complexity and freshness."}, {"product_id": "404cca0f-f3e6-4c6c-8686-dc724382fbe3", "source": "barrellbourbon.com", "source_url": "https://www.barrellbourbon.com/golddovetail", "reviewer": "Barrell", "text": "Nose: White grapefruit, and red currant illustrate a classic fruity whiskey aroma just slightly influenced by cabernet. Dunn Vineyards classic stewed cherry, sarsaparilla, and creme de menthe float by. Assorted jams such as raspberry and white grape are suggestive of Port's influence along with espresso. Palate: Bright citric acid lights up the taste buds. The Canadian whisky and varied maturation create a complex textural experience. An opening of strawberry rhubarb pie leads into lemonade as the tartness builds. It is then overtaken by creamed honey and marshmallow. Finish: Ginger ale and panela explode onto the scene, evocative of the rum casks. As they fade, a fruitier side combines with tropical notes to deliver ripe mango and candied pineapple. The finish is also just touched by the Cabernet's cranberry juice and slate."}, {"product_id": "655bbc11-175a-43ec-ba57-92e9361e39f0", "source": "barrellbourbon.com", "source_url": "https://www.barrellbourbon.com/rye", "reviewer": "Barrell", "text": "Nose: Blackberry, dried apricot and Concord grape lead off. The grape introduces woodsy tones of blonde tobacco, birch oil and dandelion root. Rye lends its familiar bouquet garni, lemon verbena, and peppermint aromatics. Meanwhile an unhurried maturation has produced cashew, tahini and nocino. Palate: The first impression mirrors the nose but here grape soda is joined by a dark amber maple syrup. Burnt marshmallow leads into rich espresso and black licorice. There's a deep umami presence of leather, black olive, and grilled onion. Finish: A burst of blanche armagnac and rosewater volatiles make way for the piquant heat of mole poblano and black pepper on the tongue. The lingering impression is of juniper, thyme, and wormwood."}, {"product_id": "24ddca1e-cf9a-4706-a590-57feeacd3781", "source": "barrellbourbon.com", "source_url": "https://www.barrellbourbon.com/whiskey", "reviewer": "Barrell", "text": "Nose: Sweet and captivating, with inviting aromas of apple pie drizzled with spring blossom honey, caramel corn and honeysuckle. It's punctuated with robust notes of resinous herbs (rosemary, bay leaf) and enriched by soft, savory tones (velouté, crushed almond). Palate: It opens sweet and herbaceous, with notes of molasses, maple sugar, Mary Jane candies, and licorice root. Finish: Mouthwatering, with a spicy signature of clove oil, red chili oil, and Rainier cherries."}, {"product_id": "1c029030-fe15-4803-9179-6640d5cd808a", "source": "bluenotebourbon.com", "source_url": "https://www.bluenotebourbon.com/products/blue-note-wheated-bourbon-101/", "reviewer": "Blue Note", "text": "Nose: Caramel, apricot, peach, cinnamon. Taste: Toffee, pastries, hazelnut, sweet oak, graham cracker. Finish: Floral, honeysuckle, honey."}, {"product_id": "8ca1cf8c-6b4c-4903-b4fe-a11bd38f2f2c", "source": "bluenotebourbon.com", "source_url": "https://www.bluenotebourbon.com/products/premium-small-batch/", "reviewer": "Blue Note", "text": "Nose: Maple, butterscotch. Taste: Maple, caramel, and vanilla. Finish: Smooth with lingering hints of vanilla."}, {"product_id": "08829f8f-069b-4b85-88f0-0778b21b366a", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskey/core/blue-run-blueprint-series-kentucky-straight-bourbon-whiskey", "reviewer": "Blue Run Spirits", "text": "Nose: Soft floral notes greet you first, layered with subtle orchard fruit. Palate: Warm baking spice unfolds alongside juicy apple and a touch of cinnamon, balanced by a gentle sweetness that adds depth without overpowering. Finish: Toasted oak rounds out the experience, leaving a lingering warmth of cinnamon and spice with a hint of dry wood heat."}, {"product_id": "bfb51ca5-c7d7-4033-95c6-e940066e78c5", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/core/emerald-1", "reviewer": "Blue Run Spirits", "text": "Nose: Dreamy butterscotch and creamy caramel lead to toasted oak and spicy peppers. Palate: A quick hit of buttercream and shishito peppers awakens the palate, followed by a blast of apples and pears, evolving into a woody sprinkling of clove and rye spices. Finish: Lingering leather, oak, and brown butter notes."}, {"product_id": "5026df8c-3777-4275-93a1-ce862c8e6f08", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/core/emerald-ii-kentucky-straight-rye-whiskey", "reviewer": "Blue Run Spirits", "text": "Nose: A bouquet of butterscotch interplays with tropical notes reminiscent to rum based grilled pineapple. Palate: The sweetness of maraschino cherry hits the palate, followed by tropical notes of mango juice, rounding out with wood spice. Finish: A full and fruity finish that builds."}, {"product_id": "1dd19d13-85c5-47b6-97b7-f08f5fee2fd4", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/core/kentucky-straight-high-rye-bourbon", "reviewer": "Blue Run Spirits", "text": "Nose: Delicious notes of pralines and orange peel, with hints of bright cherry and tobacco. Palate: Brown sugar and nuttiness start to shine, as a little bit of white pepper pops, but it's well-balanced, and slowly moves to stone fruit and dried apricot. Finish: A long finish that progresses to flavors of herbal white tea, peach, and clove."}, {"product_id": "38ec8a8b-2c98-42b5-b775-88f743d9a492", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/core/reflection-i-kentucky-straight-bourbon", "reviewer": "Blue Run Spirits", "text": "Nose: This opens with a distinct note of tart yet slightly sweet cherry on the nose with a supporting cast of butterscotch candies, mild firewood, and a hint of pancake batter. Palate: That batter becomes a stack of pancakes with vanilla-laced butter, maple syrup, and a few nuts thrown in that lead to an herb garden full of rosemary bushes. Finish: That savory note mellows out through the mid-palate as a dusting of nutmeg rounds out the finish with hints of woody maple syrup and a final echo of that tart cherry."}, {"product_id": "577c1dad-0bb9-49b7-8c61-f631ab3d9360", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/core/reflection-ii-kentucky-straight-bourbon", "reviewer": "Blue Run Spirits", "text": "Nose: A bright bouquet of warm spices and rich cocoa immediately dominate the olfactory senses and serve as a precursor to an exhilarating experience. Palate: The first sip reveals bountiful orange peel that harmonizes with farm fresh honey, followed by fresh toasted oak and tantalizing salted caramel blondies, as the palate remains preoccupied with the mid-note flavor sensations. Finish: A complex finish is led by spicy citrus oils that evolve into barrel spice and churros sprinkled with powdered sugar and a dash of cayenne."}, {"product_id": "68f22130-9720-474d-b1ec-027d9aad17c5", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/limited-releases/bourboon-rye-whiskeys", "reviewer": "Blue Run Spirits", "text": "Nose: Delicate botanical aromas, with a hint of soft pine. Palate: The sweetness of honey is balanced with the spice and subtle herbal flavors of cardamom. Finish: A harmony of barrel toast and char combined with the complex richness of cocoa."}, {"product_id": "eac8531f-7048-43f2-875a-fec6fbec3f75", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/limited-releases/flight-series-iii", "reviewer": "Blue Run Spirits", "text": "Nose: The delightful woody aroma of a cinnamon spiced chocolate confection. Palate: The luscious sweetness of plum and ripe pineapple meld with the dried fruit and dark sugars of cocoa, reminiscent of a rich fondu. Finish: A mild earthiness that builds into a caramelized sugar finish with lingering spice."}, {"product_id": "24fe4d11-037d-4803-8cb1-c1cb562bc25f", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/limited-releases/flight-series-iii", "reviewer": "Blue Run Spirits", "text": "Nose: A sweet and aromatic burst of citrus that interplays with complex spice. Palate: Bright and chewy notes of orange lead, as flavors of cinnamon, sassafras, and spearmint pop on the palate. Finish: Rich black cherry intensifies with the heat of black peppercorn spice."}, {"product_id": "9ec4344d-0199-4c36-9c92-957c5196daf2", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/limited-releases/flight-series-iii", "reviewer": "Blue Run Spirits", "text": "Nose: The freshness of green, and punch of crisp apple mellow with the floral of wildflower honey. Palate: Like a delicious bite of apple crisp, the tang of tart apples is balanced with the earthy sweetness of honey, maple, golden raisin, and caramel. Finish: A smooth, buttery finish with light char."}, {"product_id": "f210fef9-05ec-48f5-8502-1f581a976871", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/limited-releases/flight-series-iii", "reviewer": "Blue Run Spirits", "text": "Nose: A smoky and toasted aroma of nuts roasting over a summer campfire. Palate: A gourmet combination of savory dry roasted nuts mixed with candied dried fruit that's lightly drizzled with caramel and chocolate. Finish: A decadent finish of lingering caramel and warm black pepper spice."}, {"product_id": "cf92adee-8b1b-4d1d-b147-16b11e93380b", "source": "bluerunspirits.com", "source_url": "https://www.bluerunspirits.com/whiskeys/limited-releases/flight-series-iii", "reviewer": "Blue Run Spirits", "text": "Nose: A mouthwatering aroma of warm, whiskey-infused Bananas Foster. Palate: Flavors of juicy sour apple are offset with the creamy tropical notes of banana, combining with the rich and buttery toffee flavors of demerara sugar. Finish: A robust profile culminating in a sandy dry finish."}, {"product_id": "ae26c685-bdda-4d55-812d-53bbe4e92af4", "source": "bluegrassdistillers.com", "source_url": "https://bluegrassdistillers.com/products/blue-corn-bottled-in-bond/", "reviewer": "Bluegrass", "text": "Aroma: Buttered croissant, banana, warm, brown sugar and chocolate. Taste: Velvet mouthfeel, black cherry, basil, vanilla, milk chocolate and fresh croissant. Finish: dash of spice leads, chocolate, brown sugar, pear, baking spices such as nutmeg."}, {"product_id": "9c0d6c7d-5974-4f38-8b1f-eb08408d6a01", "source": "bluegrassdistillers.com", "source_url": "https://bluegrassdistillers.com/products/wheated-bourbon-bottled-in-bond/", "reviewer": "Bluegrass", "text": "Aroma: Honey, Butter, Toffee, Nut, Lemon Zest. Taste: Butterscotch, Brown Sugar, Dried Apricot, Vanilla Frosting, Smoked Oak. Finish: Toasted Butterscotch, Brown Sugar, Smoked Oak."}, {"product_id": "c0858fba-948d-482a-99f7-249289dc243b", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/caskfinished-honey-soaked-cask-finished/", "reviewer": "Boone County", "text": "Nose: Fragrant honey, vanilla and almond. Taste: A bold, complex, pleasantly sweet, and slightly spicy bourbon. Finish: Caramel, oak, and vanilla with subtle honey undertones."}, {"product_id": "d06904c2-3a23-4980-992e-ae9d588f5024", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/caskfinished-maple-cask-finished/", "reviewer": "Boone County", "text": "Nose: Bourbon forward with hints of maple. Taste: Well layered notes of caramelization, spicy oak, with slight notes of cinnamon. Finish: Smooth, soft with a subtle maple finish."}, {"product_id": "b58bf167-fc9f-48f4-ab0d-534c9ae8a79b", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/caskfinished-toasted-cask-finished/", "reviewer": "Boone County", "text": "Nose: Vanilla, almond, and light notes of toasted oak. Taste: Sweet oak, caramel, vanilla with a hint of almond biscuit. Finish: The finish is smooth with toasted almond and a pinch of cinnamon."}, {"product_id": "1c61ca97-cace-4cb8-a13b-8ba7a1db7fb5", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/essentials-small-batch-bourbon/", "reviewer": "Boone County", "text": "Nose: Light notes of aged oak, vanilla, almond, and sugar cookie. Taste: An elegant roundness; with appropriate notes of sweet oak, caramel, vanilla, and almond biscuit. Finish: A dash of aged rye and a pinch of cinnamon."}, {"product_id": "4162a6c1-9719-4622-94bb-7807241b8480", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/essentials-small-batch-rye/", "reviewer": "Boone County", "text": "Nose: Caramelized sugar, stone fruit, toasted rye bread, and a hint of cinnamon. Taste: Bold oak, robust rye, with complimentary hints of vanilla, brown sugar, and graham crackers. Finish: Smooth finish with hints of cinnamon and toasted rye."}, {"product_id": "196953c8-1a1b-4482-9eae-863603b6e516", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/founders-reserve-kentucky-bourbon/", "reviewer": "Boone County", "text": "Nose: Candied oak, a touch of light caramel, fig, apricot, and a hint of banana bread. Taste: Toasted & Caramelized American Oak, soft winter wheat, a hint of buttery roasted peaches. Finish: Long and smooth with a dash of rye and a pinch of cinnamon."}, {"product_id": "324b1251-3ab8-4fa3-85cb-20b3d9f5bdfc", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/founders-reserve-kentucky-rye/", "reviewer": "Boone County", "text": "Nose: Caramelized sugar, stone fruit, toasted rye bread, and a hint of cinnamon candy. Taste: Bold oak, robust rye, with hints of vanilla, brown sugar, and graham cracker sweetness. Finish: Continues in a long, smooth, and rich finish of sweet cinnamon and toasted rye bread."}, {"product_id": "07b198fe-9e92-43db-9c6a-957131a6ee69", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/lexingtonclub-lexington-club-bourbon/", "reviewer": "Boone County", "text": "Nose: Oak, dried fruits and a touch of caramel. Taste: Toasted oak, roasted fruit and caramel. Finish: Smooth cinnamon with a dash of rye."}, {"product_id": "b97f5e9e-f7c1-4db3-a88f-57756a1c4b55", "source": "boonedistilling.com", "source_url": "https://boonedistilling.com/limited-releases-caribbean-rum-cask-finish/", "reviewer": "Boone County", "text": "Nose: Light notes of aged oak, vanilla, almond, and sugar cookie. Taste: A satisfying roundness; with notes of oak, vanilla and caramel. Finish: Aged rye with a trace of dark carmelized sugar."}, {"product_id": "f48ff9e2-b710-47b4-b11f-ef168a312c2d", "source": "boundaryoak.co", "source_url": "https://www.boundaryoak.co/war-eagle", "reviewer": "Boundary Oak Distillery", "text": "Vivid vanilla and caramel, a perfect blend of robust oak, sweet honey, with a hint of spice. Warm and inviting."}, {"product_id": "317a5334-1011-4837-a1bb-b6b16ee0d32f", "source": "boundaryoak.co", "source_url": "https://www.boundaryoak.co/patton-bourbon", "reviewer": "Boundary Oak Distillery", "text": "Rich profile with notes of caramel, vanilla, dark oak, complemented by a hint of robust earthy spices. Bold and flavorful."}, {"product_id": "f451fd38-4f81-4210-b9c9-3ad21b1c116d", "source": "boundaryoak.co", "source_url": "https://www.boundaryoak.co/iron-mike", "reviewer": "Boundary Oak Distillery", "text": "Smooth and well rounded profile, offering flavors of caramel, vanilla bean, and a subtle oak spice with a warm, lingering finish."}, {"product_id": "74270fd4-5302-4014-b25e-a3ff986952cc", "source": "brothersbondbourbon.com", "source_url": "https://brothersbondbourbon.com/products/new-brother-s-bond%C2%AE-bottled-in-bond-straight-bourbon-whiskey-copy", "reviewer": "Brother's Bond", "text": "Candied Dark Dried Fruit: A nose of candied dark fruits like plums and cherries, followed by a palate of raisin and fig jam, sweet and slightly tangy. Rich Port Wine: A velvety, complex nose of Port wine and toasted oak, leading to a full-bodied taste with rich, fortified Port flavors. Toasted Oak. Caramel Brown Sugar: A dessert-like aroma of brown sugar, caramel, and maple syrup, with a sweet palate of butterscotch, toffee, and maple syrup. Maple Syrup. Spicy Herbs & Leather: Floral and herbal notes on the nose, with a long, warming finish of cinnamon, fig jam, mint, and a touch of smoky leather balanced by brown sugar."}, {"product_id": "ab6f0601-72cd-4ecb-b8cc-0cfb233ac5de", "source": "brothersbondbourbon.com", "source_url": "https://brothersbondbourbon.com/products/new-brothers-bond%C2%AE-regenerative-grain-bourbon-copy", "reviewer": "Brother's Bond", "text": "Honey Cornbread: Golden honey drizzles over fresh-baked cornbread, delivering a warm, sunlit sweetness rounded by a soft, comforting graininess. Light Floral & Toasted Oak: Gentle waves of smoke and char wrap around the core, unveiling layers of dry spice, seasoned wood, and a faint ember-like warmth. Cracker Jack: A nostalgic rush of caramel-coated popcorn and roasted peanuts greets the palate, offering a playful blend of sweet and savory that lingers with a buttery crunch. Warm Vanilla: Silky ribbons of vanilla weave through the sip, imparting a mellow sweetness that glows softly from start to finish."}, {"product_id": "efe15abb-4b2e-407f-b1d3-3c6a40b1bd4c", "source": "brothersbondbourbon.com", "source_url": "https://brothersbondbourbon.com/products/new-brothers-bond%C2%AE-original-cask-strength-straight-bourbon-whiskey-copy", "reviewer": "Brother's Bond", "text": "Ripe Banana, Caramel & Vanilla: Indulgent and elegant aromas of caramel and vanilla are well integrated with the richness of sweet ripe banana. Walnut & Dried Fruits: The taste intensity of dried fruit and orange marmalade is rounded out by mild earthy walnut flavors. Warmed Rye Bread & Honey: Across the palate, adding complexity to the flavors are warm rye bread and honey notes. Leather & Subtle Smoke: A hint of leather and subtle smoke leads to a long, lingering and warm rye spice finish."}, {"product_id": "e5bc6e42-7eaa-4fff-ad64-5076d665b9ea", "source": "brothersbondbourbon.com", "source_url": "https://brothersbondbourbon.com/products/new-brothers-bond%C2%AE-american-blended-rye-whiskey-copy", "reviewer": "Brother's Bond", "text": "Caramel: Rich caramel cream. Candied Fruit: A sweet intense dried raisin note. Rose Petals & Mint: A delicate combination of mint and rose petals with a hint of aromatic grapes. Ripe Pineapple: Bright and vibrant tropical fruit with a soft creamy note. Port Wine. Cinnamon Brown Sugar: A warm spicy, caramelized, and charred wood-like finish."}, {"product_id": "a2dc7f95-a152-46d7-b6c1-9a5aebad370b", "source": "cooperscraft.com", "source_url": "https://www.cooperscraft.com/bourbon/barrel-reserve/", "reviewer": "Brown-Forman", "text": "Nose: Fresh hewn oak with hints of smoke and char are spiced with hints of cinnamon and leather atop a layer of orchard and citrus fruit. Sweetened with a sprinkling of vanilla wafer crumbs. Taste: Caramel and cotton candy coat fresh apple, pear and citrus fruit atop vanilla wafers dusted with sharp cinnamon. Finish: Assertive cinnamon spice softens to a lingering apple and clean oak note."}, {"product_id": "348ae087-abc4-4f0d-916c-c882d9b2b3e7", "source": "jackdaniels.com", "source_url": "https://www.jackdaniels.com/whiskey/jack-daniels-bonded-triple-mash", "reviewer": "Brown-Forman", "text": "Aroma: Dried fruit, oak, and toast. Taste: Honey sweetness with underlying grain spice and dry oak. Finish: Well rounded with slightly spicy finish."}, {"product_id": "d76d2622-f65f-4ddf-b37e-5e99c5433128", "source": "oldforester.com", "source_url": "https://www.oldforester.com/products/117-series-warehouse-k/", "reviewer": "Brown-Forman", "text": "Aroma: Creamy chocolate, caramel, and brown sugar lead, with a hint of golden raisin and foreshadowing on the pepper the finish will unveil. Taste: Full bodied and rich viscosity, peripheral spice, and a touch of black cherry alongside bitter molasses. Finish: Robust yet balanced spice finish completes the story of the well-known complexity which is the K warehouse."}, {"product_id": "ea4bcebf-142f-4cf2-acd0-a2c27967d68d", "source": "oldforester.com", "source_url": "https://www.oldforester.com/products/old-forester-100-proof-rye-whisky/", "reviewer": "Brown-Forman", "text": "Aroma: Moody brown sugar and molasses are rounded out by a hint of malt and playful notes of root beer and dark fruits. Taste: Burnt sugar, blood orange and a hint of black pepper with sweet licorice and subtle oak undertones. Finish: Long and lingering with black pepper and citrus oils offering complex texture and toasted malt rounding out the flavor."}, {"product_id": "bf527262-7758-443c-85f4-15d6379f9624", "source": "oldforester.com", "source_url": "https://www.oldforester.com/products/old-forester-86-proof/", "reviewer": "Brown-Forman", "text": "Aroma: Bright notes of citrus fruits, tropical fruits and delicate florals complimented by pound cake sweetness, subtle clove spice and undertones of lightly toasted oak. Taste: Citrus zest and ripe pear lead the flavor with an underpinning of fresh mint and hints of clove spice. Finish: Fresh spearmint carries through along with clove spice and warm toasted oak."}, {"product_id": "4c6dc9f4-c0ce-4708-b6ca-d7ae09c7345d", "source": "oldforester.com", "source_url": "https://www.oldforester.com/products/the-117-series-high-angels-share/", "reviewer": "Brown-Forman", "text": "Aroma: Bold, with rich caramel, toasted coconut, dried cranberry, and dark brown sugar amongst a background of intense oak spice. Taste: Full-bodied, opens with molasses and dense dessert elements then trails into anise and celery seed. Finish: Extensive, full palate, with roaring spice, roasted coffee, and black pepper."}, {"product_id": "6da037aa-0fa9-40d3-a12c-1b9bb1afe9bd", "source": "woodfordreserve.com", "source_url": "https://www.woodfordreserve.com/whiskey/malt-whiskey/", "reviewer": "Brown-Forman", "text": "Nose: Soft nutty notes drizzled with light caramel and milk chocolate coat a layer of fruit character (apple, dried fruit, tropical fruit). Hints of brown spice, savory mint and brown sugar mingle with a rich note of freshly milled toasted oak. Taste: Dark chocolate and caramel coated nuts are dried out with a dusting of cocoa powder and brown spice. A fruit medley brightens a trace of toasted coconut and rich, bright oak character. Finish: Nutty and subtly sweet chocolate malt notes."}, {"product_id": "2d314b56-fa30-4e65-9216-36ea81a51ab9", "source": "woodfordreserve.com", "source_url": "https://www.woodfordreserve.com/whiskey/masters-collection-sonoma-triple-finish/", "reviewer": "Brown-Forman", "text": "Nose: Vanilla and cinnamon dusted grilled pineapple slices and red plum fruit. Taste: Vine and red fruit warmed with rich vanilla bean and oak notes. Finish: Long oak and red grape tannins."}, {"product_id": "623e83c4-1d38-41e3-b717-6169d2f4e332", "source": "woodfordreserve.com", "source_url": "https://www.woodfordreserve.com/whiskey/masters-collection/", "reviewer": "Brown-Forman", "text": "Nose: Dark cherries and candied oranges sprinkled with cocoa powder awaken to bright pepper, clove, nutmeg, and cedar wood. Taste: Rich oak, cinnamon, clove, and tobacco box fade into robust dried dark fruit notes of raisin and dried cranberry. Finish: The bright spice notes linger and give way to berry fruit and dark cocoa."}, {"product_id": "7966b926-215d-4c96-9409-55ba938095ab", "source": "woodfordreserve.com", "source_url": "https://www.woodfordreserve.com/whiskey/rye-whiskey/", "reviewer": "Brown-Forman", "text": "Nose: Spicy with distinct notes of rye, black pepper, cedar and cassia bark sweetened with a dusting of marzipan. Hints of pear, apple and almond dance in its depths. Taste: Clove, rye, mint, molasses, sorghum and honey mingle together with hints of apple and malt. Finish: Long and sweetly spiced."}, {"product_id": "fd63e2cf-530d-44bb-8d7f-c0333d5f8f47", "source": "woodfordreserve.com", "source_url": "https://www.woodfordreserve.com/whiskey/wheat-whiskey-bottled-in-bond/", "reviewer": "Brown-Forman", "text": "Nose: Toasted whole wheat bread smothered in apple butter. Taste: Delicate apple butter and dried berry compote fruitiness atop a wheat cracker. Finish: Long with dried berry fruit."}, {"product_id": "a9290e43-f2c0-42a5-8382-0a5a450caa3e", "source": "woodfordreserve.com", "source_url": "https://www.woodfordreserve.com/whiskey/wheat-whiskey/", "reviewer": "Brown-Forman", "text": "Nose: Aromatic spiced (cinnamon and cedar) and cooked fruit (apple, pear, banana) mingle with a delicate floral character sweetened with light vanilla bean and brown sugar notes. Taste: Spicy applesauce and toasted coconut notes enliven an earthy mint and cocoa nib mix. Finish: Dry, subtle cocoa nibs and lingering apple peel."}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "9a005cfa-9ba5-4211-a4d8-9c6c1e2fdb96", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/benchmark/benchmark-bonded/", "reviewer": "Buffalo Trace", "text": "A nose of citrus and honey follows through on the palate, with a touch of light oak, caramel and vanilla. Long, smooth finish."}, {"product_id": "c456074c-9175-4396-aa66-c8d2afa31611", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/benchmark/benchmark-full-proof/", "reviewer": "Buffalo Trace", "text": "The scent of deep brown sugar and chocolate are followed by the bold taste of caramel and baking spice. The finish is long and rich."}, {"product_id": "d13d0f5b-da9d-49fd-b7b2-ad247b93a921", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/benchmark/benchmark-single-barrel/", "reviewer": "Buffalo Trace", "text": "A nose of toasted oak and baking spice leads to a complex palate with notes of caramel and citrus undertones."}, {"product_id": "2135836d-bbfc-4ec2-966e-ed13d32b888e", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/benchmark/benchmark-small-batch/", "reviewer": "Buffalo Trace", "text": "The aroma of vanilla and oak gives way to delightful hints of caramel, leather and honey."}, {"product_id": "41785139-9bb4-49d9-a970-6c636990933f", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/benchmark/benchmark-top-floor/", "reviewer": "Buffalo Trace", "text": "Scents of subtle sweetness and baking spice are followed by flavors of light citrus, butterscotch and oak."}, {"product_id": "215d7b77-2dc0-4c3e-8243-8c5011da32cb", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/blantons-single-barrel/blantons-gold-edition/", "reviewer": "Buffalo Trace", "text": "Hints of spicy rye and tobacco on the nose, followed by caramel and honey, dark fruit and citrus notes. The palate emulates the same complex aroma with rye, tobacco and honey. Oak and vanilla contribute to an extremely long and harmonious finish."}, {"product_id": "59261e91-f52e-4c0c-b4e1-706d7dafd221", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/blantons-single-barrel/blantons-special-reserve/", "reviewer": "Buffalo Trace", "text": "A slightly floral nose that conveys whispers of cedar and raisin in between soft vanilla notes. The palate has a light airy feel to it. The taste of vanilla and toffee dance around subtle notes of dried fruit and white pepper."}, {"product_id": "cf563d80-9983-42a5-8b85-72e953a5d0d3", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/blantons-single-barrel/blantons-straight-from-the-barrel/", "reviewer": "Buffalo Trace", "text": "Dark chocolate, caramel with earthy undertones of walnut and hazelnut on the nose. The palate delivers warm vanilla, oak, toasted nuts and a rich spiciness with hints of butterscotch or honey. The high alcohol by volume is intense and powerful, yet inviting. Unfiltered, uncut, unbelievable."}, {"product_id": "a02b19cf-ef25-4cfc-a0c1-8d81e36ab205", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/buffalo-trace/kosher-whiskey-straight-rye/", "reviewer": "Buffalo Trace", "text": "The spice of rye, with hints of citrus and clove."}, {"product_id": "ac5f7ed1-9ea4-4dee-860a-630a9850bcc7", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/colonel-e-h-taylor-jr-distillers-council/", "reviewer": "Buffalo Trace", "text": "A grain-forward nose with biscuit and pastry notes. The palate offers toasted sugar, dark caramel, crème brûlée, plum dessert and nougat."}, {"product_id": "df1b2aee-6024-4998-b9da-e5cb0fc779a1", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-barrel-proof-rye/", "reviewer": "Buffalo Trace", "text": "On the nose it has an aroma of white pepper and nutty undertones, with a touch of fresh floral and candied apricot. A sip brings a range of complex flavors, balancing the sweet, dried stone fruit with pepper and oaky dryness. The lasting finish is full and sweet as honey, concluding an exceptional experience."}, {"product_id": "469b98f8-d0d2-4ef8-b38d-29790c7d9189", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-bottled-in-bond/", "reviewer": "Buffalo Trace", "text": "The nose opens with warm vanilla, seasoned oak, charred undertones, and a drizzle of maple sweetness. On the palate, balanced sweetness and baking spices mingle with gentle wood note The lingering finish carries oak and vanilla into soft caramel with a hint of cherry."}, {"product_id": "1fe998af-2032-44e2-abcd-fc3dd57bd965", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-cured-oak/", "reviewer": "Buffalo Trace", "text": "A complex bourbon whiskey with layers of depth. Notes of vanilla, toffee and figs are followed by subtle undertones of dry oak."}, {"product_id": "fc3a6623-a643-4e30-b6ac-c7a2a587668c", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-old-fashioned-sour-mash/", "reviewer": "Buffalo Trace", "text": "The flavor begins with a floral aroma and an undertone of freshly baked bread. The palate is unusually fresh and light; like honey drizzled over toast. There is a clean finish with hints of leather."}, {"product_id": "53a4582e-b515-4864-8df8-3ef576d19bc6", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-straight-rye/", "reviewer": "Buffalo Trace", "text": "Aroma full of dried fruit, black pepper and a touch of fresh dill. A small sip brings an array of flavors both sweet and savory with a terrific balance of dark spices and subtle caramel overtones. The finish is especially pleasing with an oaky dryness that lingers just long enough."}, {"product_id": "44918564-2d22-4f7c-8f77-477916677088", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-warehouse-c-bourbon/", "reviewer": "Buffalo Trace", "text": "Nose of cherry cobbler with rum sauce and a hint of oak. Palate of cherry cola, vanilla bean and toasted oak. Finish that is long and lingering with a hint of spearmint, coffee, raisin bread and anise."}, {"product_id": "61f07102-ff37-42ea-b001-e5168ade6175", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/e-h-taylor-jr/e-h-taylor-jr-warehouse-c-tornado-surviving/", "reviewer": "Buffalo Trace", "text": "On the nose, the aroma of dried fig and cloves initially jumps from the glass. This is followed by baking spice and an oaky dryness that provides balance. A small sip fills the mouth with flavors of jam-like fruit, vanilla and a touch of smoke. The finish quickly builds in dark spices with hints of tobacco leaving a lasting final impression of this bourbon."}, {"product_id": "94c65de6-b481-43c6-8e2e-ae99a39033ba", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/eagle-rare/eagle-rare-12/", "reviewer": "Buffalo Trace", "text": "Opens with a sweet, oaky aroma and delicate hints of almond. On the palate, it delivers bold complexity, featuring subtle vanilla and toasted oak. A rich, lingering finish with warm notes of toffee."}, {"product_id": "5e76f787-6779-43ab-9142-1ff45bdb832f", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/eagle-rare/eagle-rare-25/", "reviewer": "Buffalo Trace", "text": "Notes of intense cherry, oak, dark chocolate and an icing drizzle beginning on the nose. The palate is a balance of vanilla, dark fruit and butterscotch. An extremely long finish with lingering notes of rickhouse floor, baking spice and black pepper."}, {"product_id": "aea26489-410e-4fc6-bb66-e22080862b5d", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/eagle-rare/eagle-rare-30/", "reviewer": "Buffalo Trace", "text": "Deep mahogany in color, Eagle Rare 30 opens with layered aromas of baked cherry, brown sugar, caramel and honey, complemented by subtle nuttiness, warm tobacco and well-integrated oak with a hint of smoke. The palate is rich and expansive, coating the mouth with sweet aged stone fruit and caramel. Its finish is long and velvety, evolving from sweetness to a gentle smokiness, with a refined oak character that remains smooth, balanced and enduring."}, {"product_id": "cbe43c05-43a8-44ce-ac27-8e84291d8c43", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/old-charter-oak/old-charter-chinkapin-oak/", "reviewer": "Buffalo Trace", "text": "Nose: Cherries and spearmint with hints of floral notes Palate: Fresh herbs and honey Oak Finish: Warm baking spices followed by dark chocolate."}, {"product_id": "fbc03624-0b46-4e7c-ba91-fe230bb3f248", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/old-charter-oak/old-charter-mongolian-oak/", "reviewer": "Buffalo Trace", "text": "A nose of pecan, caramel and pine. Notes of cedar, clove, butterscotch and dark chocolate. Black pepper and smoked oak finish."}, {"product_id": "189f87a6-9327-4458-bcdd-ced2bf3bdf65", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/sazerac-rye-whiskey/sazerac-rye-100-proof/", "reviewer": "Buffalo Trace", "text": "Sazerac Rye Whiskey 100 Proof features aromas of clove, vanilla, anise, and pepper. On the palate, it reveals subtle notes of candied spices and citrus, leading to a smooth finish with hints of licorice. The higher proof amplifies these flavors, offering a richer, more balanced drinking experience."}, {"product_id": "c3f92530-8fa9-4220-a930-9ed22936a4d9", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/sazerac-rye-whiskey/sazerac-rye-18-year-old/", "reviewer": "Buffalo Trace", "text": "Very mature, with notes of oak, leather, molasses and allspice. Long, warm finish is preceded by notes of mint, eucalyptus, cinnamon, vanilla and lingering pepper."}, {"product_id": "528021f6-d34a-4c5a-a0e8-b7989bdd6c9f", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/sazerac-rye-whiskey/sazerac-rye-full-proof/", "reviewer": "Buffalo Trace", "text": "This high-proof rye opens with bold aromas of rye spice, fresh dill, smoky oak, and warm spice, immediately signaling its intensity and depth. On the palate, it delivers a surprisingly smooth sweetness up front, followed by floral and herbal notes, supported by rich oak and classic rye grain character throughout. The finish is lightly peppery with a late rye spice that gently lingers, offering warmth and complexity without being overwhelming."}, {"product_id": "5eb06779-9c0f-427e-b51d-32059e256e87", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/sazerac-rye-whiskey/sazerac-straight-rye-whiskey/", "reviewer": "Buffalo Trace", "text": "Aromas of clove, vanilla, anise and pepper. Subtle notes of candied spices and citrus. The big finish is smooth with hints of licorice."}, {"product_id": "0da1ca74-0d75-41c3-bcb4-30223dceb774", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/sazerac-rye-whiskey/thomas-h-handy-sazerac/", "reviewer": "Buffalo Trace", "text": "Powerful, lush and boldly spicy. Flavors of toffee, fig cake and candied fruit, followed by mint, cinnamon and clove. The finish ultimately reveals subtle notes of allspice, coconut and nutmeg. Long and warm."}, {"product_id": "17ac728d-290b-41de-be17-06e29b2214d3", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/traveller/traveller-full-proof/", "reviewer": "Buffalo Trace", "text": "Traveller Full Proof delivers a richer, higher-impact expression of the original Traveller blend, with amplified notes of caramelized sugar, baking spice, and toasted oak. Building on the smooth, approachable foundation of Traveller, this full proof release brings added depth with flavors of vanilla, warm toffee, dark fruit, and a long, satisfying finish."}, {"product_id": "f8f3e413-681f-4ba0-82e1-9527e6b2632e", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/traveller/traveller-whiskey-blend-40/", "reviewer": "Buffalo Trace", "text": "Complex aromas of vanilla, aged fruit and buttery shortbread rounded off by caramel and a touch of oak. The palate has just a touch of sweetness, followed by spice, toasted nut and oak flavors. A robust finish."}, {"product_id": "72ff9d8f-155d-402a-ac10-4a662a474f49", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/van-winkle/van-winkle-special-reserve-12-year/", "reviewer": "Buffalo Trace", "text": "Highlighted by light aromas of dried mango, cocoa, fruit and spiced peach. Flavors of honey, oak and tobacco dance on the palate. The finish is balanced and dry, with a lingering tingle."}, {"product_id": "e1d796d0-47a0-4342-b255-7829d508340e", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/w-l-weller/daniel-weller/", "reviewer": "Buffalo Trace", "text": "Nose: Fresh and nutty, with notes of orange zest, hazelnut, cinnamon and caramel. Palate: Well-rounded blend of bold oak, sweet honey and orchard fruits. Finish: A complex oak-forward finish complemented by baking spice and leather notes."}, {"product_id": "cd5af37b-e4b9-46ea-b9f7-950ae699ad1d", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/w-l-weller/w-l-weller-single-barrel/", "reviewer": "Buffalo Trace", "text": "Nose of cherry and mint, fading to vanilla. Caramel and baking spices with hints of cocoa explode on the palate. Finish of cinnamon, coffee and a hint of pepper."}, {"product_id": "11522d27-ad80-4200-8fe6-517cae5e0ea7", "source": "buffalotracedistillery.com", "source_url": "https://www.buffalotracedistillery.com/our-brands/w-l-weller/william-larue-weller/", "reviewer": "Buffalo Trace", "text": "Fragrant scents of caramel corn, new leather, plums, light toffee and pipe tobacco. The palate tastes of marshmallow, salted almonds, nougat, figs and dates. This whiskey finishes smooth, composed and flavorfully sweet."}, {"product_id": "65abf120-cfe1-4cd9-970b-17bd0a5ba2a2", "source": "calumetbourbon.com", "source_url": "https://www.calumetbourbon.com/16-year-old-citation", "reviewer": "Calumet Farm", "text": "Nose: Upon Uncorking: Beginning notes of woody-char and smoke subside to reveal softer scents of toasted almonds and fresh-cut summer hay. Nose: After Breathing: As the spirit opens up, lighter notes of citrus and orange mix with darker floral and cherry scents to complete the experience. Taste: Notes of saturated-oak and warm rye spice open the palate, allowing flavors of cherries, dark fruits, and baking spice to present fully - Fresh baked bread, toasted toffee, and a light corn meal dryness round out the rich flavors. Finish: Imparting a lighter than expected finish, this spirit's bold flavors give way to a subtle warmth, notes of toasted grains, and a smokiness that proceed the mellowing of wood sugars and oak."}, {"product_id": "31fb5688-bed1-44ba-9c02-e692f81abafc", "source": "calumetbourbon.com", "source_url": "https://www.calumetbourbon.com/15-year-old-whirlaway", "reviewer": "Calumet Farm", "text": "Nose: Upon Uncorking: notes of oak and wood char are notable. Nose: After Breathing: complex scents of dark fruit and sweet corn. Taste: Bold flavors of oak, aged spice and toasted grains are present while toffee and a subtle smoky-sweetness roll across the palate. Finish: A lingering finish mellows, leaving sweet tobacco and rye flavors with a slightly dry mouth feel."}, {"product_id": "3b1aefe5-f4c8-46d6-a9b2-bf60eee089e6", "source": "calumetbourbon.com", "source_url": "https://www.calumetbourbon.com/smallbatch", "reviewer": "Calumet Farm", "text": "Nose: Sweet notes of caramel and butterscotch are forward. Taste: Smooth accents of banana bread and light brown sugar mix well with a smokey char flavor. Finish: Delicate and sweet with a round finish, approachable and lingers long on the palate."}, {"product_id": "f7ebbe1c-9560-4532-bafb-7fa40d20ffed", "source": "calumetbourbon.com", "source_url": "https://www.calumetbourbon.com/8yo", "reviewer": "Calumet Farm", "text": "Nose: A full, rich aroma of aged oak with deep undertones of vanilla. Taste: A hint of vanilla and fruit upfront rolls into soft notes of white pepper and a full woody taste. Finish: A balanced sweetness lingers as a rich yet subtle caramel flavor fades away warming the entire palate as it retreats."}, {"product_id": "b625e425-fb6c-4d50-b14b-959a3c86639f", "source": "castleandkey.com", "source_url": "https://castleandkey.com/products/castle-key-experimental-series-hungarian-tokaji-casks", "reviewer": "Castle & Key", "text": "Orange creamsicle, fenugreek, cinnamon roll, sugarcane, jasmine tea, wheat cracker, currant preserve. Cotton candy, grape, rum raisin, orange zest, light baking spice, sherry, marzipan, caraway, roasted cacao nib. Finish: Macerated strawberry, molasses, tobacco leaf, long lingering and heavy finish."}, {"product_id": "45c3996a-eefd-4032-a731-bf7108aae181", "source": "castleandkey.com", "source_url": "https://castleandkey.com/products/castle-key-experimental-series-vino-de-naranja-rye", "reviewer": "Castle & Key", "text": "Pomegranate syrup, eucalyptus, honeycomb, candied orange peel, vanilla, burnt thyme, sassafras, cola, dried blueberry, light floral. Chai, gingersnap, toasted rye bread, dried orange, date, dried ginger, chewy, toffee pudding, vinous. Finish: Spice cake, sarsaparilla, rye spice, candied ginger."}, {"product_id": "7154d694-6689-453e-b8f4-da51cdf8bf9e", "source": "castleandkey.com", "source_url": "https://castleandkey.com/products/small-batch-7-year-wheated-bourbon", "reviewer": "Castle & Key", "text": "Pastry Dough, Buttercream, Baked Apricot, Strawberry Preserve, Honeycomb, Birch Beer, Jasmine, Nutmeg. Cane Sugar, Dried Peaches, Rainier Cherries, Sassafras, Leather, Black Pepper. Finish: Full bodied, medium building spices to bruleed sugar and sage."}, {"product_id": "5ad7172e-f6e4-46bb-8f5f-19aa7ca65bab", "source": "chattanoogawhiskey.com", "source_url": "https://chattanoogawhiskey.com/product/chattanooga-whiskey-111/", "reviewer": "Chattanooga Whiskey", "text": "Chocolate covered cherry, toasted coconut and cinnamon. Full bodied with a warming, malty finish."}, {"product_id": "8729c697-fd43-42ba-b4b4-fd7ab54c2431", "source": "chattanoogawhiskey.com", "source_url": "https://chattanoogawhiskey.com/product/chattanooga-whiskey-99/", "reviewer": "Chattanooga Whiskey", "text": "Fruit cake, cola spice, sage and toasted rye. Full bodied with a malty sweet & spicy finish."}, {"product_id": "f7cd2d28-b570-4251-816c-778c5c0cc4e1", "source": "chickencockwhiskey.com", "source_url": "https://chickencockwhiskey.com/whiskey/island-rooster/", "reviewer": "Chicken Cock", "text": "Nose: An elegant array of spices, pepper, with a hint of rye grassiness and sweet molasses softly touched with oak overtones. Palate: A tremendous complexity of spices, vanilla, butterscotch and pepper, beautifully complimented with just enough rum sweetness to complete the full flavor profile. Finish: Very long and enjoyable, with the rye characteristics predominant, but wonderfully enhanced with a touch of sweet, rich molasses and buttery mouthfeel."}, {"product_id": "3ae7209c-591a-49e6-a757-36a9ab671149", "source": "chickencockwhiskey.com", "source_url": "https://chickencockwhiskey.com/whiskey/mizunara/", "reviewer": "Chicken Cock", "text": "Aroma: Fresh sandalwood, butterscotch, baking spices, leather. Palate: Graham cracker, cracked pepper, pastry, exotic wood spice. Finish: Cinnamon, clove, bright cherry, and soft oak tannins."}, {"product_id": "348af5d8-1d0b-477d-8b49-27d40ee15244", "source": "chickencockwhiskey.com", "source_url": "https://chickencockwhiskey.com/whiskey/red-stave/", "reviewer": "Chicken Cock", "text": "Nose: Hints of dark chocolate, toasted oak and dried fruit. Palate: Traditional dark chocolate, bold caramel and vanilla notes quickly evolves into pear, apple, cherry and red currant fruit flavors before presenting a long finish with bright cranberry tartness with a hint of black pepper. Finish: Complex long, lingering, nutmeg and clove spice. A perfect complex blend of flavors."}, {"product_id": "a129aa6f-95aa-4788-9bda-5397706b23ce", "source": "chickencockwhiskey.com", "source_url": "https://chickencockwhiskey.com/whiskey/small-batch/", "reviewer": "Chicken Cock", "text": "Nose: Orange zest, vanilla pastry, clove, candied ginger. Palate: Palate-coating flavor of butterscotch, honey, vanilla custard, and orange peel. Finish: Apricot, vanilla extract, toffee, red apple skin."}, {"product_id": "7815b078-7a1a-4663-a132-40edf195b63b", "source": "chickencockwhiskey.com", "source_url": "https://chickencockwhiskey.com/whiskey/wheated-bourbon/", "reviewer": "Chicken Cock", "text": "Palate: Cordial cherries, hints of cream soda and caramel. Finish: Baked dough, brown sugar, dried fruit, and gentle baking spices."}, {"product_id": "b66936b8-f9a9-4bd8-ba23-69fecce72a1e", "source": "copperandkings.com", "source_url": "https://copperandkings.com/product/kings-proof-bourbon/", "reviewer": "Copper & Kings", "text": "Aroma: Sweet Oak, Leather & Apple Skin. Flavor: Tobacco, Fresh-cracked Black Pepper & Baked Apple."}, {"product_id": "f6c30325-7250-458b-9e7e-ec2d9e3df7c4", "source": "bulleit.com", "source_url": "https://www.bulleit.com/whiskeys/bulleit-american-single-malt", "reviewer": "Diageo", "text": "While we've subbed our signature high rye grains for 100% malted barley, our American Single Malt still has that signature, subtle Bulleit spice with aromas of sweet vanilla and toasted oak. It's light and fruity on the palate with hints of red fruit and pear, which follow into a smooth finish of oaky caramel and subtle cocoa notes."}, {"product_id": "439d43c8-1f2b-4c0f-8243-9d408a51d28d", "source": "bulleit.com", "source_url": "https://www.bulleit.com/whiskeys/bulleit-rye-10-year-old", "reviewer": "Diageo", "text": "On the nose, it offers caramel and toffee, with a notable rye character. On the palate, there is a blend of smoothness and spice, balancing pear-like fruitiness, sweet vanilla, and a dry, buttery oakiness with classic, full-bodied rye notes. The finish provides gentle spice and vanilla, ending with a hint of toasted oak."}, {"product_id": "b7681b40-3184-4712-b0a7-e74881b921de", "source": "bulleit.com", "source_url": "https://www.bulleit.com/whiskeys/bulleit-rye-whiskey", "reviewer": "Diageo", "text": "Russet in color, with rich oaky aromas. The taste is exceptionally smooth, with hints of vanilla, honey, and spice. Finish is crisp and clean, with long, lingering flavors."}, {"product_id": "f9679aa6-8bca-487d-a4d5-909a1b0552cb", "source": "distillery291.com", "source_url": "https://distillery291.com/colorado-rye-whiskey-small-batch-aspen-wood-staves/", "reviewer": "Distillery 291", "text": "Scent & flavor: cinnamon, maple, spicy oak tannins."}, {"product_id": "0ddee24d-db90-43a3-a9a8-bfea22def1d8", "source": "distillery291.com", "source_url": "https://distillery291.com/american-whiskey-aspen-charcoal-mellowed/", "reviewer": "Distillery 291", "text": "Scent & flavor: fresh cut leather, fruit, floral, light oak."}, {"product_id": "5aef9219-9207-4ab0-b0fc-5d7f8b0c82d0", "source": "distillery291.com", "source_url": "https://distillery291.com/hr-bourbon-whiskey/", "reviewer": "Distillery 291", "text": "Scent & flavor: gingerbread, pueblo chile, lemon meringue, plum, pine sap, port wine, cinnamon bark."}, {"product_id": "eecbf8e7-ad3e-4a00-b9b1-94d65086fffb", "source": "distillery291.com", "source_url": "https://distillery291.com/product-291-good-guy-american-whiskey/", "reviewer": "Distillery 291", "text": "Scent & flavor: gingerbread, smoked mango & soft tropical fruit, lavender, cedar, rich toffee, read hot candy, cinnamon baked apples."}, {"product_id": "dbe189fb-f715-48f3-bfa5-54139a581943", "source": "distillery291.com", "source_url": "https://distillery291.com/product-291-e-colorado-whiskey-batch-15/", "reviewer": "Distillery 291", "text": "Scent & flavor: orange marmalade and apple butter on toast, brown sugar, toasted oak, creme brulee, dried stone fruits."}, {"product_id": "ca49fc62-85ad-4417-bf28-9f050c48dc36", "source": "distillery291.com", "source_url": "https://distillery291.com/product-xv-anniversary-colorado-whiskey/", "reviewer": "Distillery 291", "text": "Scent & flavor: Dried Apricot, Molasses, Toffee, Gingerbread, Cinnamon, Cardamom, Charred Oak."}, {"product_id": "6c5fa388-1546-4644-bf3e-bedf6e950827", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-blenders-cut-bourbon", "reviewer": "Doc Swinson's", "text": "apricots, brown sugar, peanuts, toasted almond, charred oak, dark chocolate, and cream."}, {"product_id": "a7d0eb5e-8dcc-4ac1-9fcd-8e9190712fee", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/bossa-nova", "reviewer": "Doc Swinson's", "text": "Nose: Sweet vanilla, cinnamon, and cookies dominate the nose. Palate: Brown butter, apple pie crust, gooey cinnamon buns with a hint of sage. Finish: Sweet and unfolding, a flavor that keeps on giving."}, {"product_id": "a0d28e3a-d749-406f-8e99-ee6dab48d6a3", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/dos-padres", "reviewer": "Doc Swinson's", "text": "Bright citrus, pepper, vanilla, and caramel with agave syrup in the finish."}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "119d930d-0608-444e-9bfb-85019e80440f", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/el-cuerpo", "reviewer": "Doc Swinson's", "text": "Nose: Leather, Italian plums, dark chocolate, black tea. Palate: dried figs, plum jam, spiced tea, honey, roasted almonds. Finish: chocolatey with fruits that dance on the tongue."}, {"product_id": "a0a22b6c-f9a0-472e-b2e1-263e57c9097f", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/french-toasted", "reviewer": "Doc Swinson's", "text": "Dark chocolate, stone fruits with toasted notes of vanilla, clove, and baked apple bread."}, {"product_id": "d2d6a182-d0e8-4abf-89c8-d1c616d523ae", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/garryana", "reviewer": "Doc Swinson's", "text": "Nose: Kansas City BBQ smoke, sweet plum sauce. Palate: Molasses cookies, confectioners sugar, black tea, and fruit leather. Finish: A little cocoa and fig jam to cling to the tongue."}, {"product_id": "0c3277a3-eabd-497f-aa70-ace4c2830910", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/l-esprit", "reviewer": "Doc Swinson's", "text": "Nose: Orange marmalade, Soda bread, citrus and marzipan. Palate: Golden raisins, wildflower honey, dark chocolate, dried tobacco, crème brûlée and candied orange peels. Finish: Exceptional balance of sweet and citrus notes, a smooth sipping bourbon with a toasted oak finish."}, {"product_id": "a88ba344-8c54-45de-bb4c-301148d3f41e", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/la-mente", "reviewer": "Doc Swinson's", "text": "Nose: Almond kringle, orange peels, spiced tea. Palate: Dried apricots with honey, choclate dipped orange peels, roast nuts. Finish: A rich bourbon with notes that keep unfolding as you sip it."}, {"product_id": "205bd66d-0e63-486b-a41a-4f1265ebdee6", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/reefer-madness", "reviewer": "Doc Swinson's", "text": "Nose: Bright citrus, Creme brulee, toasted rye bread. Palate: Orange marmalade, whipped honey butter on rye toast, with slight earthy biscuit-ey notes, finishes with sweet tobacco. Finish: A delightful ensemble that greets you with citrus marmalade, and falls to fire-roasted hatch chili pepper and toasted rye bread. Moves onto a subtle, yet long-lasting sweet tobacco that stays on your palette (think of a long draw on a rich and sweet cigar; bright leading into rich earth and dried fruits)."}, {"product_id": "20aee4f7-d208-4497-a3fb-f938f7d82aa9", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/sercial-malmsey-madeira", "reviewer": "Doc Swinson's", "text": "grilled apricot, caramel, vanilla, roast walnuts, dark cherries, and orange zest."}, {"product_id": "b8df30b2-c51f-49d3-9c28-751db94bd534", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/tawny-port", "reviewer": "Doc Swinson's", "text": "Dark chocolate tart cherry, toffee, tannin, toasted oak, cranberry."}, {"product_id": "d5374528-7226-48f2-9e1d-e17806573c0a", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/the-forgotten-one", "reviewer": "Doc Swinson's", "text": "Orange Marmalade, caramel, oak, stone fruits, minerals, and dry mixed nuts."}, {"product_id": "a58308fa-a83f-4e23-b6df-a66328e9c99e", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-exploratory-cask/tres-amigos", "reviewer": "Doc Swinson's", "text": "Grandma's canned pears in syrup, butterscotch, golden raisins, and subtle pie crust."}, {"product_id": "f1e4e5fd-bcb7-445c-b2ff-f4ada689e23c", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/library-high-proof-triple-cask", "reviewer": "Doc Swinson's", "text": "Marzipan, dark cherries, whipped cream, allspice, caramel, rich oak tannins."}, {"product_id": "82a3f978-cdcf-4288-94be-a4677f8403f1", "source": "docswhiskey.com", "source_url": "https://www.docswhiskey.com/session-blend", "reviewer": "Doc Swinson's", "text": "Nose: candied almonds, toasted oak, sweet vanilla, and cacao powder. Palate: dried fruits, brown sugar, candied pecans, rye toast, caramel corn, and buttercream texture."}, {"product_id": "982d94ff-fcce-4aeb-acdc-b6f0d9a27580", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-1-kelvin-collaboration", "reviewer": "Four Gate Whiskey Company", "text": "Nose: The finish barrels are front and center with a huge waft of maple syrup. Behind that, there is a spicy cinnamon, some vanilla and caramel, with a sweet red fruit undertone. Taste: Oloroso Sherry hits the front palate with a burst of sweet fortified wine and simple syrup. The mid palate gets traditional high-rye bourbon notes of vanilla, black pepper, and oak, while the rear palate gets a molasses and brown sugar sweetness from the rum finish. Finish: Medium-to-long, there are prevalent barrel tannins and rye spices that linger on the tongue while a boozy rum finish coats the inside of the mouth."}, {"product_id": "e9e22907-b032-4d34-8c21-86403360f591", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-2-outer-orbit-loop", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Initial burst of citrus and pine with underlying black pepper spices. Taste: Tangy citrus greets the front palate with heavy cinnamon and baking spices on the mid palate. The rear of the palate gets pine needles and a slight nuttiness. Finish: Medium-Long, the citrus lingers on the periphery while black pepper and cinnamon intermingle with gin notes of pine and juniper."}, {"product_id": "fdfa222b-036f-453a-adce-2c86ee70a1e5", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-4-split-stave-by-kelvin", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Dark cocoa powder with hints of creamy crème brûlée. Taste: Oak is front and center on the tip of the tongue while sweet custard and cinnamon notes strike the mid-palate. Finish: Long and rich, the oak notes intermingle with dark chocolate and earthy tobacco for an intense finish."}, {"product_id": "a6b0d9ee-8dd4-4d89-8397-eb1aeefa5219", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-5-foundation", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Sweet fruits and vanilla cream are joined by graham cracker and rye pepper. Taste: A touch of heat on the front palate is followed by sweetness on the mid-palate with more custard and cream, followed by baking spices, cinnamon, oak, and pie crust. Finish: Medium-long in length, the rye notes are balanced with sweet cinnamon toast and rye spice."}, {"product_id": "e1e81936-6770-4a12-ac66-3764ce982d03", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-9-andalusia-key", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Sweet fruits, fortified wine, molasses, and Vanilla. Taste: Where the sherry plays a big role on the nose, the underlying bourbon and rum finish take the forefront on the palate with traditional rye-bourbon spice and dark burnt brown sugars on the periphery. Finish: Medium-short in length, the finish is dry and sherry-forward with a pepper spice that lingers a bit on the rear palate."}, {"product_id": "f6118660-4782-45de-9c92-ea62633a1e5f", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-10-split-stave-by-kelvin-rye", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Mint, toasted marshmallows, oak, candied citrus. Taste: The front palate is greeted by sweet crème brulee while toasted marshmallows line the perimeter. The rear palate gets a hint of black pepper and spices with pleasing warm oak. Finish: Medium in length, spicy notes and marshmallows mingle on the mid-palate."}, {"product_id": "77265ae7-0c2f-4ff0-b7ba-f876fdc20912", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-12-kelvin-collaboration-ii", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Vanilla, caramel, molasses, and sweet red fruit. Taste: Rich and decadent, the PX Sherry is evident on the front palate followed by traditional vanilla and oak bourbon notes on the mid palate. Brown sugar sweetness coats the periphery. Finish: Long, viscous, and mouth-coating. The molasses and red fruit linger throughout."}, {"product_id": "e28852e0-ac05-469a-b351-06c1599f4767", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-14-old-sherry-pike", "reviewer": "Four Gate Whiskey Company", "text": "Nose: After it breathes, there are nutty characteristics with spice and vanilla. Taste: Nutty, fruity and plenty of black pepper spice, the palate gets plenty of traditional bourbon flavors paired with sweet sherry notes. Finish: Long, with almonds and faint red grapes interplaying throughout."}, {"product_id": "35c1637a-1dfa-43f0-8972-79b9baec0d53", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-16-rye-downunder", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Nutty and fruity with citrus and black pepper. Taste: Cashews and almonds are followed by lemon zest, black pepper, and baking spices. Finish: Medium with traditional rye flavors intermingling with sweet red fruits."}, {"product_id": "9465db14-6001-477e-b66d-d7320d77bbf9", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/newpage", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Toasted marshmallow, cinnamon, baking spices, nutmeg, and cloves. Taste: Sweet buttered cinnamon buns, cloves, vanilla extract, black pepper, and hints of mint. Finish: long and satisfying with peppery spices and notes of citrus."}, {"product_id": "3f780fb8-ddd5-4b42-84ed-f9fba1239de0", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-19-kelvin-collaboration-iiii", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Peppery rye spice, dark fruits, oak, and vanilla. Taste: Black pepper, lemon zest, and sweet corn followed by plums, dark cherries and raisins. Finish: Long and lingering with rye spice and sweet rum molasses."}, {"product_id": "5f440a72-e955-4629-a3cc-161bfa8cb8dc", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-20-four-by-four", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Pepper, spice, vanilla, molasses, maple syrup, butter. Taste: Citrus zest, oranges, light caramel, sweet simple syrup and dark rum. Finish: Long, the rye spices fade out to be replaced by low, sweet dark rum notes."}, {"product_id": "2a21ff1c-47ec-419e-be2f-f1f2123ece71", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-21-port-perry-perry", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Pepper, spice, citrus zest, red fruit, jam. Taste: Citrus zest, oranges, black pepper and cloves, plums, raspberry. Finish: Medium, long citrus, black pepper and dark red fruits with sticky preserves."}, {"product_id": "8e015c70-8d8c-44e8-a0af-678bb76fa8d1", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-22-barossa-creek", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Sweet vanilla, cloves, cinnamon. Taste: Vanilla, light butterscotch, oak, candied lemon drops, orange zest. Finish: Medium, sweet brown sugar, citrus, and barrel tannins linger."}, {"product_id": "877cab3e-57e3-4c49-8beb-134b3d902992", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-23-barossa-creek2", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Plums, dates, raisins, spices, citrus. Taste: Oak, black pepper, dark grapes, sweet red fruit, and mild citrus. Finish: Medium, prunes, oak tannins, sweet baking spices, black pepper."}, {"product_id": "5f5cd2be-e29e-4a7b-8ddf-6e6a237e8d5d", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-24-brbn-downunder", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Citrus zest, cashews, light red fruits, black pepper. Taste: Oak, vanilla, sweet berries, almonds, black pepper. Finish: Medium-long, vanilla, and light barrel tannins intermingle with nuts and fruit."}, {"product_id": "514b7976-b9a1-467f-b75e-4f5ff1d1c2ed", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-25-andalusia-key-rye", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Spicy black pepper, citrus, dark molasses, cashews, faint red fruits. Taste: Candied citrus, spicy black pepper, baking spices, raisins, maple syrup. Finish: Medium; black pepper, maple syrup, molasses, dark rum, light citrus."}, {"product_id": "4fc2d916-a707-4965-a241-5f6f3f47d4ae", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-26-andalusia-key-rye2", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Sweet fruits, molasses, floral notes, black pepper. Taste: hints of nuts and sweet fruits, baking spice on the mid-palate & sweet caramelized brown sugar on the rear palate. Finish: Medium; vanilla, pepper spice."}, {"product_id": "be392c9b-e16d-4aac-a5c7-383dd642fe7c", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-27-split-stave-by-kelvin-rye2", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Vanilla, toasted marshmallow, black pepper, oak. Taste: Sweet spearmint with sugar notes and simple syrup. Finish: Medium; mint notes fade to the rear and finish with a crisp touch of oak."}, {"product_id": "2b507815-4a1d-451e-b97c-099bd5f4990c", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/batch-28-kelvin-v", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Chocolate and almonds with hints of dark stone fruit and cherries. Taste: Oak, crème bruleé, sweet vanilla, light custard, floral hints, & baking spices. Finish: Long and lingering, the sweet fruits and molasses continue for days."}, {"product_id": "7d6484bf-6998-499b-8a34-b075baaf3228", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/tkc6-kelvin-collaboration-vi", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Tart fruits, gummy candies, molasses, vanilla. Taste: Tart Cherries, chocolate, maple syrup, and oak. Finish: Long; sweet red fruits, brown sugar, oak."}, {"product_id": "16a4af8c-fe09-4239-972f-c6ee4b20714a", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/copy-of-batch-29-triple-oak", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Sweet vanilla, baking spices, light oak. Taste: Caramel and brown sugar with hints of sandalwood throughout the mid-palate. Finish: Medium; spicy wood notes permeate the mid palate."}, {"product_id": "1358c3f7-6d3b-435c-ac4a-13774beda674", "source": "fourgatewhiskey.com", "source_url": "https://www.fourgatewhiskey.com/mws-brazilian-ambruana", "reviewer": "Four Gate Whiskey Company", "text": "Nose: Cinnamon, frosting, cloves, baking spices. Taste: Gingerbread hits the front palate and continues throughout. Sweet baked goods, cinnamon buns. Finish: Long; the gingerbread cookie flavor slowly fades to a lingering vanilla and oak finish."}, {"product_id": "ec1f9a93-112f-4b54-aff2-20ddbe6a75db", "source": "fourrosesbourbon.com", "source_url": "https://www.fourrosesbourbon.com/bourbon/2017-al-young-50th-anniversary", "reviewer": "Four Roses", "text": "Nose: Exhibits aromas of sweet caramel and floral honeysuckle. Palate: The palate offers flavors of fresh peaches and apricots, encompassing a luxurious and warm fig and rich oak. Finish: The finish showcases a hint of mint."}, {"product_id": "b3ef4b30-24d1-48f1-bfe5-3b0cc6e32e75", "source": "fourrosesbourbon.com", "source_url": "https://www.fourrosesbourbon.com/bourbon/single-barrel-oesq", "reviewer": "Four Roses", "text": "Nose: Red berries, honey, caramel, and light oak. Palate: Floral aromas and vanilla. Finish: Soft and lasting."}, {"product_id": "4ffc83fa-feff-47b8-8b08-bace4f6dec7a", "source": "fourrosesbourbon.com", "source_url": "https://www.fourrosesbourbon.com/bourbon/small-batch-select", "reviewer": "Four Roses", "text": "Nose: Raspberries, cloves & nutmeg. Palate: Apricot, berries, vanilla & light oak. Finish: Lingering spearmint with a light touch of cinnamon."}, {"product_id": "b5d008aa-3cb8-4562-9321-a86aa1861562", "source": "shop.freyranch.com", "source_url": "https://shop.freyranch.com/products/100-wheat-whiskey-vault", "reviewer": "Frey Ranch", "text": "Tasting Notes: Aromatic profile of Bananas Foster, butterscotch, and orange peel, backed up by a long finish of Nutella, honey, tea chest, and espresso"}, {"product_id": "bfae2460-6a9a-4dd9-9eee-3f6bef6a9eaf", "source": "garrisonbros.com", "source_url": "https://www.garrisonbros.com/our-babies/bottled-in-bond/", "reviewer": "Garrison Brothers", "text": "Nose: Oaky and smoky, with tobacco, leather, and campfire kindling. Palate: Toasted oak and heavy wood sugars—robust, earthy, deep, and full. Drinks like a cross between maple syrup and homemade root beer, rich with sassafras and sarsaparilla. Finish: Layers of caramelized dark chocolate follow, mingling with plums, nectarines, roasted almonds, and toffee for a mouth-watering finish."}, {"product_id": "b622fd69-603d-41c7-89f6-1ae99aad642b", "source": "garrisonbros.com", "source_url": "https://www.garrisonbros.com/our-babies/estacado/", "reviewer": "Garrison Brothers", "text": "Nose: Concentrated and savory, with oak, roasted corn, leather and hints of red hots. Palate: Silky, with maple syrup, cinnamon sticks and orange marmalade. Port influences of dates, raisins and baking spices. Finish: Crisp, with lemon zest and black pepper. Lingering notes of toasted oak."}, {"product_id": "34c8d04a-0308-41b9-8444-a1588b97ac5b", "source": "garrisonbros.com", "source_url": "https://www.garrisonbros.com/our-babies/hye-rye/", "reviewer": "Garrison Brothers", "text": "Nose: Subtle with spiced cherries, raisins, new leather and orange blossoms. Palate: Warm and welcoming waves of baking spices with sweet hints of molasses, caramel and vanilla. Finish: Spicy and savory with black pepper, clove, cinnamon, ginger and warm sorghum."}, {"product_id": "13c8999a-c270-41e6-9674-3e4425a41183", "source": "garrisonbros.com", "source_url": "https://www.garrisonbros.com/our-babies/laguna-madre/", "reviewer": "Garrison Brothers", "text": "Nose: Sweet caramel blondies and toffee with warm hints of spiced raisins. Palate: Creamy, decadent with vanilla bean, hazelnut, saltwater taffy, milk chocolate. Hints of root beer. Finish: Long and smooth with hints of Almond Joy candy bar and white chocolate."}, {"product_id": "60b02e26-c147-4530-9350-3d5ee37db70f", "source": "garrisonbros.com", "source_url": "https://www.garrisonbros.com/our-babies/sonora/", "reviewer": "Garrison Brothers", "text": "Nose: Rich aromas of sweet corn, oak, and rye spices mingle with vanilla and butterscotch. Palate: The palate bursts with black pepper and cinnamon, followed by a bouquet of citrus zest, almond tea, and wildflower honey. Finish: Lingering finish of brown sugar and crème brûlée."}, {"product_id": "5f3b3800-1b49-4ba0-ba87-d0fc1ca3bd30", "source": "greenriverwhiskey.com", "source_url": "https://greenriverwhiskey.com/single-barrel-wheated/", "reviewer": "Green River", "text": "Taste: Orange peel, apricot, and cinnamon are balanced by toffee and pastry. A honeyed, round mouthfeel with hints of hazelnut leads to a lasting finish of traditional Kentucky flavor. Finish: A soft, round, and lasting finish of traditional Kentucky flavor."}, {"product_id": "e7b3f257-093c-4d62-beff-e5c578391dac", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/sweet-mash-bourbon/", "reviewer": "Hard Truth", "text": "Aroma: Caramel, pecan, clove, fruit, and oak. Taste: Toffee, caramel, cherry, and sweet cream. Finish: Warming coffee, vanilla, and oak that linger on the palate."}, {"product_id": "1d082e0c-25e4-4a6f-921e-d7e9e2c1a075", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/sweet-mash-rye-whiskey/", "reviewer": "Hard Truth", "text": "Aroma: Notes of sweet maple and stone fruit blend perfectly with bold rye spice and a touch of honey that awakens the palate. Taste: Bright and bold dark sweet cherry slowly builds to cracked black pepper, delicious bruleed sugar, and oak. Finish: Rich cherry syrup and delicate notes of vanilla slowly fade to warming clove and cinnamon for a lasting finish."}, {"product_id": "2e9eba94-9480-4731-bb81-1cdafeefb2ee", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/high-road-rye-whiskey/", "reviewer": "Hard Truth", "text": "Aroma: Apricot jam, honey, baking spice, and graham cracker. Taste: Rich vanilla, maple, custard, and spice that coat the tongue. Finish: Bold and lingering caramel that fades to honey, coffee, and nougat."}, {"product_id": "f89ccf87-6d49-437e-b153-949663483e09", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/double-oaked-bourbon/", "reviewer": "Hard Truth", "text": "Aroma: Rich caramel and vanilla lead to tobacco, a touch of leather, and subtle apple. Taste: Sweet and balanced maple syrup and oak quickly build to a delicious hint of smoke. Finish: A complex burst of smoke, fig, and tobacco lingers on the palate before building to a spice forward finish."}, {"product_id": "c10abf1d-c828-4944-afb9-aa6cd77c501e", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/mizunara/", "reviewer": "Hard Truth", "text": "Aroma: Sweet notes of cinnamon, toasted coconut, and ginger, paired with a touch of fruit and spice. Taste: Rich cherry leads into layers of toffee and caramel. Finish: Cherry lingers on the palate, gradually giving way to tobacco, cracked pepper, and vanilla."}, {"product_id": "c60c3172-faab-4030-8985-a680fc0c2fbd", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/barrel-finish-reserve-smr-sauternes/", "reviewer": "Hard Truth", "text": "Aroma: Rich golden raisin, allspice, and anise with a touch of brown sugar. Taste: Sweet pastry notes quickly shift to rich raisin and warming baking spice. Finish: Warm and lingering candied fruit with bold pepper, allspice, and a touch of honey."}, {"product_id": "cf8d534f-2f5c-4b92-a10c-ed57ddb10e82", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/barrel-finish-reserve-smr-px-sherry/", "reviewer": "Hard Truth", "text": "Aroma: Rich notes of vanilla custard, cassis, and rye spice. Taste: Bright fruit, brûléed sugar, and warming spices. Finish: Concord grape jelly and smooth vanilla fade to dark chocolate and clove."}, {"product_id": "ffb12c6e-a701-445b-81c4-2f9aed986fe7", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/barrel-finish-reserve-smr-px-brandy/", "reviewer": "Hard Truth", "text": "Aroma: Bold notes of maple syrup, baking spices, and candied fruit. Taste: Sweet brown sugar and maple are quickly overtaken by soft fruit notes, rich clove, cinnamon, and pepper. Finish: A warming touch of cinnamon and shortbread give way to toffee and a hint of oak."}, {"product_id": "1ac22b16-76b5-4733-9195-f8106a9198f1", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/barrel-finish-reserve-smr-cognac/", "reviewer": "Hard Truth", "text": "Aroma: Warm, with bright spiced pear, vanilla, and orange zest. Taste: Baked apple, brown sugar crumble, and bold baking spice. Finish: Long and inviting, with fruit and a touch of maple fading to black pepper and toffee."}, {"product_id": "dcebdf74-5011-43e9-9590-4d0e759ea427", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/barrel-finish-reserve-2024-blend/", "reviewer": "Hard Truth", "text": "Aroma: Spiced pear, crème brûlée and toffee shift to candied fruit, oak, and vanilla. Taste: Rich stone fruit and grape slowly fade to butterscotch, vanilla custard, and clove. Finish: Warming rye spice and plum fades to rich tobacco and cherry with a touch of allspice."}, {"product_id": "aa6ad361-0e79-419b-b775-cedbfb923699", "source": "hardtruth.com", "source_url": "https://hardtruth.com/spirits/harvest-rye/", "reviewer": "Hard Truth", "text": "Aroma: Spiced pear, toffee, and rich caramel. Taste: Caramel and soft mocha open the palate, giving way to sweet crème brûlée, bold baking spice, and ripe orchard fruit. Finish: Warm and lingering with hints of dark chocolate, oak, and spiced honey that fade to toffee and subtle, smoked vanilla."}, {"product_id": "057a7b18-7f17-4a94-9d9a-017ecb1dca17", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/bernheim-barrel-proof.php", "reviewer": "Heaven Hill", "text": "Aroma: Oak staves and fresh bread. Taste: Buttery notes of caramel and honey with clove spice. Finish: Soft and complex; notes of honey and caramel."}, {"product_id": "5a2d5847-b4c7-4ee7-b2ae-b693b0e34e17", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/elijah-craig-barrel-proof-rye.php", "reviewer": "Heaven Hill", "text": "Aroma: Baking spices with sweet, molasses note. Taste: Complex and well-balanced. Stewed fruit with cinnamon and nutmeg. Finish: Long and warm. Butterscotch with lots of rye spice."}, {"product_id": "bddd4754-bdff-49d1-bf76-dfe3d001bf73", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/elijah-craig-rye.php", "reviewer": "Heaven Hill", "text": "Aroma: Dark chocolate with spices and a hint of smoke. Taste: Rich baking spices and honey backed up with smooth oak influence. Finish: Long, lingering."}, {"product_id": "f7a744e5-61ce-48fa-be7f-3753ecf2d85d", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/elijah-craig-single-barrel18.php", "reviewer": "Heaven Hill", "text": "Aroma: Aged oak, spiced vanilla, with notes of mint and chocolate. Taste: Richly textured nutty and semisweet, initial bursts of honey give way to toasted wood and pleasant char. Finish: Lively and engaging, then lingers with vanilla and pepper."}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "c42731e8-e689-4b78-96cc-b8a595b6596c", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/elijah-craig-toasted-rye.php", "reviewer": "Heaven Hill", "text": "Aroma: Toasted oak and crème brulee. Almonds and hazelnuts. Taste: Soft, creamy mouthfeel. Milk chocolate with subtle baking spices. Finish: Softly warming with lots of long, drawn-out spices."}, {"product_id": "05ee433c-e811-4edb-9564-8eea065c80f7", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/evan-williams-bourbon.php", "reviewer": "Heaven Hill", "text": "Aroma: Light with deep vanilla and mint. Taste: Notes of oak, brown sugar, and caramel. Finish: Medium to long."}, {"product_id": "ed69db61-c84e-4aca-8343-740ceedae9e2", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/evan-williams-single-barrel-vintage.php", "reviewer": "Heaven Hill", "text": "Aroma: Dark caramel, sweet oak and charred wood. Taste: Lush and spicy, oak with honey, apple and orange notes. Finish: Long, graceful and relaxed."}, {"product_id": "0b5941b4-596c-4186-a12b-ab76da828467", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/ew-bottled-in-bond.php", "reviewer": "Heaven Hill", "text": "Aroma: Caramel with hints of vanilla, oak, and barley. Taste: Citrus on top of vanilla, and black pepper. Finish: Warm, long, dry."}, {"product_id": "b51df6cb-a83d-42d5-aab0-6316cb640e11", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/kentucky-straight-rye-whiskey.php", "reviewer": "Heaven Hill", "text": "Aroma: Toasted oak and almonds. Taste: Creamy orange marmalade and chocolate with nutmeg, white pepper spices and honey sweetness. Finish: Orange oil with rye spices, crème brûlée, and charred oak."}, {"product_id": "30d891f3-3c99-40a0-845a-3b6c108d27a1", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/kentucky-straight-wheated-bourbon-whiskey.php", "reviewer": "Heaven Hill", "text": "Aroma: Sweet and smoky with polished oak and savory barbecue spices. Taste: Sandalwood and tropical fruit accented by a pop of white pepper. Finish: New leather and dried grasses with a linger of complex spices."}, {"product_id": "d81a2d4e-8824-4f80-8822-da3f649884d1", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/old-fitzgerald-7-year-old.php", "reviewer": "Heaven Hill", "text": "Aroma: Graham crackers and honey. Light citrus and summer fruit notes. Taste: Rich and viscous. Fresh bread, brown sugar, and baking spices. Finish: Long-lasting richness, Brown sugar sweetness with cinnamon fades to a hint of oak."}, {"product_id": "6dc8af92-47be-4a82-8cc9-16c0a2750a6c", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/pikesville-straight-rye.php", "reviewer": "Heaven Hill", "text": "Aroma: Dusty cocoa notes with oaky smoke underneath. Taste: Dry and spicy, with honeyed rye and cloves. Finish: Soft vanilla and baking spices."}, {"product_id": "8deddf36-a1b6-4c8f-b912-ab944ecbceb4", "source": "heavenhilldistillery.com", "source_url": "https://heavenhilldistillery.com/rittenhouse-rye.php", "reviewer": "Heaven Hill", "text": "Aroma: Dried fruits, toffee, and sweet peppers. Taste: Clean, rich, cocoa, citrus, cinnamon, nutmeg and vanilla. Finish: Lingering maple-like spiciness."}, {"product_id": "9787f079-8f38-49b7-bed5-7e684235d386", "source": "heavensdoor.com", "source_url": "https://www.heavensdoor.com/double-barrel-whiskey", "reviewer": "Heaven's Door", "text": "Nose: Maple with milled grains and a light nuttiness. Dried berries, vanilla custard, and toasted oak. Palate: Caramel, dough, dark cherry, Meyer lemon. Dry oak, vanilla bean, dried apricot. Coconut backed by orange oil and cocoa with woody overtones."}, {"product_id": "0d28b508-acfe-4361-b483-461a993c1032", "source": "highwest.com", "source_url": "https://highwest.com/pages/limited-releases", "reviewer": "High West", "text": "Nose: Honeycrisp apple, golden raisins, zested kumquat, graham cracker crust, wildflower honey, malted milk chocolate, toasted oak spice, honeycomb. Palate: Peach and cherry cobbler, gingersnaps, roasted marshmallows, puffed wheat cereal, cocoa nibs, molasses, dried thyme, charred barrel staves. Finish: Financier cakes with grated almonds and brown butter."}, {"product_id": "46fcf681-ea62-44d3-b8f4-42abd064763a", "source": "ship.highwest.com", "source_url": "https://ship.highwest.com/products/bottled-in-bond-rye", "reviewer": "High West", "text": "Nose: Luxardo cherry, basket of fresh picked limes, churros, chocolate chip cookie dough, apple pie in the windowsill, leather. Palate: Chocolate orange sticks, juicy ripe watermelon, lemon peel, baked goods in the forest, creamy toffee, oak rocking chair. Finish: Orange flesh, cool mint."}, {"product_id": "ac4363d2-2e80-4915-98db-5ead8df9a8b7", "source": "ship.highwest.com", "source_url": "https://ship.highwest.com/products/rendezvous-rye", "reviewer": "High West", "text": "Nose: Orange peel, dried apricots, mint, clove, pine, and caramelized sugar. Palate: Bold spice with ginger and cinnamon; underlying sweet notes of molasses, vanilla, macaroon, and toasted oak. Finish: Lively rye spice fades away to lingering notes of caramel, orange zest, and tobacco."}, {"product_id": "a7f9db3e-4c89-433a-9bcf-a17c9af18055", "source": "hkyoungbourbon.com", "source_url": "https://hkyoungbourbon.com/toasted-bourbon", "reviewer": "H.K. Young", "text": "Toasted Small Batch opens with aromas of maple syrup and cinnamon candies before unfolding into flavors of toasted marshmallow, nutmeg, and dried fruit. The finish is long and eloquent, with notes of oak, tobacco, and dark cherry."}, {"product_id": "bc25170f-6134-45b9-b4c2-96e9165f0b75", "source": "hkyoungbourbon.com", "source_url": "https://hkyoungbourbon.com/wheated-blend", "reviewer": "H.K. Young", "text": "This whiskey opens with aromas of vanilla and raspberry pastries, followed by flavors of buttercream frosting, spice, and dark chocolate."}, {"product_id": "3ca63a98-891f-44fb-9d1a-b49bad0df0aa", "source": "jepthacreed.com", "source_url": "https://jepthacreed.com/product/bloody-butchers-creed-90-corn-bourbon/", "reviewer": "Jeptha Creed", "text": "Nose: Piping hot cinnamon rolls, and brown sugar, with a hint of cedarwood. Palate: A wonderful full body mouth feel with bright flavors of citrus and sweet sorghum, followed by hints of cardamom. Finish: A robust finish of tart cranberries and pink peppercorn that tingles your tongue. With an extended finish of cinnamon and butter toffee."}, {"product_id": "05b00d14-6662-4b32-8362-8a8ee0815629", "source": "jepthacreed.com", "source_url": "https://jepthacreed.com/product/bottled-in-bond-bourbon/", "reviewer": "Jeptha Creed", "text": "Nose: Sweet orange creme brulee, followed by bold baking spices, and dried cranberries. Palate: Light caramel, vanilla, cinnamon, and lemongrass with undertones of sweet oak. Finish: Long smooth buttery finish with whispers of ginger and cinnamon that dance across your tongue."}, {"product_id": "8dbd6da4-54c2-4930-8c70-bbc5b3889c77", "source": "jepthacreed.com", "source_url": "https://jepthacreed.com/product/jeptha-creed-solera/", "reviewer": "Jeptha Creed", "text": "Nose: Inviting mix of Mulled Spice, Honey, Semi-Sweet Pear & Fresh Cedar Palate: Opens with a medium bodied spritz, leading into Well-Seasoned Oak and Smoked Pepper on the front followed by Cocoa Powder, Toasted Sugar and Hints of Cream Finish: Lingering Spice, Hint of Licorice, and echoes of a Crisp Lit Maduro Cigar"}, {"product_id": "c263a39c-622d-47d0-9352-ad09694ce2b5", "source": "jepthacreed.com", "source_url": "https://jepthacreed.com/product/red-white-and-blue-bourbon/", "reviewer": "Jeptha Creed", "text": "Nose: Complex balance of red berry fruits, bread pudding, nutmeg, and clove. Palate: Rich buttery caramel with toasted nuts, dried fruit, toffee, and cinnamon. Finish: A full finish of dried fruit, sweet oak, and baking spices."}, {"product_id": "fb55589a-65b5-409a-adf5-2e19948f4fd7", "source": "jepthacreed.com", "source_url": "https://jepthacreed.com/product/six-year-old-wheated-bourbon/", "reviewer": "Jeptha Creed", "text": "Nose: Butter and toasted almond with a hint of warm croissant. Palate: Fresh baked artisanal cinnamon bread with a honey glaze, followed by tobacco, and a touch of chocolate. Finish: A long, light, refreshing finish of white pepper, dark cherry, and crème brûlée."}, {"product_id": "928433b9-e4ee-4645-9f5c-49025142af21", "source": "journeyman.com", "source_url": "https://www.journeyman.com/spirits/kissing-cousins-whiskey/", "reviewer": "Journeyman", "text": "From the initial floral sweetness to the delightful citrus notes, Batch 12 of Kissing Cousins offers a truly memorable tasting experience. With each sip, indulge in the luxurious blend of creamy caramel, gentle citrus, and oak undertones, leading to a refined and satisfying finish."}, {"product_id": "48a0b413-26c7-4d74-99be-a06b6340d771", "source": "journeyman.com", "source_url": "https://www.journeyman.com/spirits/double-oaked-rye-whiskey/", "reviewer": "Journeyman", "text": "Enjoy layered flavors of caramel, vanilla, and spice in every smooth and balanced sip."}, {"product_id": "bdf091b8-7353-40a1-8990-2c38fc15ac3b", "source": "journeyman.com", "source_url": "https://www.journeyman.com/spirits/winston-a-fox-2/", "reviewer": "Journeyman", "text": "Herbaceous notes of grass and pepper give way to cinnamon, caramel, and cherry, with hints of toffee and maple, and a curious whisper of banana."}, {"product_id": "07b05189-4b73-45cc-8409-10b8c5e8cbc8", "source": "journeyman.com", "source_url": "https://www.journeyman.com/spirits/high-rye-500/", "reviewer": "Journeyman", "text": "Built on a 7-year-old bourbon heavy rye foundation, this whiskey opens with notes of dipped red berries, dark caramel, and seasoned oak accented by a subtle savory richness. Layers of crème brûlée, candied nuts, and vibrant rye spice unfold across the palate, while finishing in a single malt barrel imparts a refined thread of smoke that sharpens the spice and deepens the complexity. The finish is long and warming, carrying hints of cocoa, charred wood, and lingering baking spice."}, {"product_id": "3f951267-f900-459a-ac8e-68a386681d77", "source": "luckysevenspirits.com", "source_url": "https://luckysevenspirits.com/buy-now/", "reviewer": "Lucky Seven", "text": "Strawberry jam, pear, and magnolia give way to chocolate-covered cherries, spiced pecans, apple, and a refreshing hint of mint and lemon."}, {"product_id": "7d1eb0a1-4290-4cb9-b862-02ec87613dd1", "source": "luckysevenspirits.com", "source_url": "https://luckysevenspirits.com/buy-now/", "reviewer": "Lucky Seven", "text": "Perfect balance of poached pear, silky tobacco, and toasted pecans. A staple for every bourbon enthusiast."}, {"product_id": "35d13f5e-32d7-4b2d-8455-0892143d642d", "source": "luckysevenspirits.com", "source_url": "https://luckysevenspirits.com/our-collection/", "reviewer": "Lucky Seven", "text": "Light fruit, allspice, caramel, and vanilla. Quintessential Kentucky bourbon, a harmonious blend of flavors."}, {"product_id": "3691bb24-8845-41ac-85e8-ff1e29a95a97", "source": "luckysevenspirits.com", "source_url": "https://luckysevenspirits.com/our-collection/", "reviewer": "Lucky Seven", "text": "A unique profile of cinnamon, brown sugar, and oatmeal raisin cookie. Finished in toasted virgin Amburana casks, offering a warm, inviting experience with a rich, viscous finish."}, {"product_id": "538a7b33-2069-4070-80b9-d0364c36c38c", "source": "michters.com", "source_url": "https://michters.com/25-year-kentucky-straight-rye/", "reviewer": "Michter's", "text": "Cascading flavors with rich vanilla, coffee, and a hint of orange, crystallized dried fruit, spicy pepper finish."}, {"product_id": "30b49000-0d52-4cc3-b93c-cda2269c4bf7", "source": "michters.com", "source_url": "https://michters.com/bombergers-pfg/", "reviewer": "Michter's", "text": "Nose: Burnt sugar, spice, chocolate opening up into floral. Palate: A beautifully integrated and complex whiskey bursting with exquisite fruit and spice, surrounded by toasty, sweet notes with an elegant bouquet. Finish: Full bodied, luxurious, with creamy mouthfeel that has lingering soft spice and chocolate."}, {"product_id": "5dfb46a2-5167-488e-be47-1ae7459219a6", "source": "michters.com", "source_url": "https://michters.com/celebration-sour-mash-2025/", "reviewer": "Michter's", "text": "This release is a captivating experience of the harmonious compliments of thoughtfully aged bourbon and rye barrels. The artistry across the palate includes salted toffee, black cherry, and dark velvety chocolate ganache transitioning through to the citrus, floral, tea and baking spices of beautiful ryes. The intrigue continues as it evolves into an experiential cascade of seemingly endless complex, luxurious flavors with a finish that memorializes its elegance and technical precision."}, {"product_id": "e0025b73-2b2d-4db3-b0fd-f3b3c90cbb26", "source": "michters.com", "source_url": "https://michters.com/sour-mash/", "reviewer": "Michter's", "text": "Warm toasted burnt sugar notes with spice, sweet, smoky fruit, candied cherries, and honeyed vanilla. Starts out like a bourbon, finishes like a rye."}, {"product_id": "31496e91-3eb3-4e6f-9092-7a534d8bd11c", "source": "michters.com", "source_url": "https://michters.com/us1-american-whiskey/", "reviewer": "Michter's", "text": "Deep butterscotch and vanilla notes, hints of caramel and dried fruit with a ripened fruit finish."}, {"product_id": "70cc16bc-939e-474c-ac84-5d86114bb7f0", "source": "michters.com", "source_url": "https://michters.com/us1-kentucky-straight-rye/", "reviewer": "Michter's", "text": "Spice with peppery notes, citrus, butterscotch, oak."}, {"product_id": "16faacbe-2567-4785-ba77-93b277f8fc2c", "source": "milamandgreenewhiskey.com", "source_url": "https://milamandgreenewhiskey.com/products/milam-and-greene-provisions-bourbon", "reviewer": "Milam & Greene", "text": "Nose: Warm and inviting, with aromas of honey-drizzled oak, roasted peanuts, orange zest, and baking spices. Subtle undercurrents of maple sugar and dried tobacco emerge with time in the glass. Palate: Rich caramel, toasted vanilla and sweetness open the palate, followed by waves of dark cherry, sweet cornbread, and a hint of cinnamon. Finish: Expressive but easy - perfect for a late afternoon. A slow fade of charred oak and burnt sugar gives way to a lingering hint of cracked pepper, dark cocoa, and worn leather - leaving for a dry, satisfying echo."}, {"product_id": "449d2c3d-2678-4c1f-ad36-4795f4a92e91", "source": "milamandgreenewhiskey.com", "source_url": "https://milamandgreenewhiskey.com/products/milam-greene-very-small-batch-straight-bourbon-whiskey-finished-with-charred-french-oak-staves", "reviewer": "Milam & Greene", "text": "Nose: Mixed dark berry cobbler, charred marshmallow, French toast and tons of baking spice. Palate: Ripe dark fruits, caramel, black tea and biscuit. Finish: Long and lingering with notes of black pepper and cardamom."}, {"product_id": "41b981c0-8a1e-431d-b61d-3150e8afdc70", "source": "milamandgreenewhiskey.com", "source_url": "https://milamandgreenewhiskey.com/products/milam-and-greene-live-oak", "reviewer": "Milam & Greene", "text": "Nose: Caramel candy, grape nuts, breakfast cereal, biscuit, earth, dusty oak, marzipan. Palate: A viscous oily mouthfeel with big, sweet notes of caramel and honey on the front, creamed corn, oak, nutmeg, and almond round out the midpalate. Finish: A medium to long finish with notes of honey, oak, black pepper, and herbaceous mint linger."}, {"product_id": "b7ddf758-65e8-42af-8cf9-2df0723c6373", "source": "milamandgreenewhiskey.com", "source_url": "https://milamandgreenewhiskey.com/products/milam-and-greene-wildlife-bluebonnet", "reviewer": "Milam & Greene", "text": "Nose: Wildflower honey, ripe melon, charred oak, chocolate cake. Palate: Baking spice and grain, opening to honey, marzipan, and chocolate malt balls. Finish: Long and elegant; honey, cardamom, gentle menthol."}, {"product_id": "34b943b5-7ceb-4203-9053-5bd183e1ac18", "source": "milamandgreenewhiskey.com", "source_url": "https://milamandgreenewhiskey.com/products/triple-cask-cask-strength", "reviewer": "Milam & Greene", "text": "Nose: Hefty cinnamon, cedar, hazelnut, vanilla, and floral notes. Palate: Spice-forward cinnamon & clove, with brown sugar and hazelnut to balance. Finish: Long and warm with chocolate, oak, and lingering caramel."}, {"product_id": "db92b193-4219-49fa-a5e9-922d7e0379e8", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-6-year-old-malted-rye/", "reviewer": "New Riff", "text": "Nose: Savory, Floral Fruit, Powdered Sugar, Balanced Oak and Vanilla Fruits (Plum Skin, Pear), everything complex and layered. Palate: Plump, rounded medium-full palate; finely dovetailed elegant spices; Saltwater Taffy, Fruits, Clove, and an interesting toasty-malty note. Finish: Focused Spice with Clove and Pink Peppercorn. Elegant and refined."}, {"product_id": "8f4394fd-04af-41b8-9ef8-45c573f8d478", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-8-year-old-rye/", "reviewer": "New Riff", "text": "Nose: Rounded and ripe with rye grass, notes of cinnamon, clove, and red apple. Palate: Fulsome, medium body; drying entry, lightly oaky with a sweeter core; slow development of spicy flavors; juicy, intense midpalate of spearmint/clove/apple, along with a lovely, aged grassy-mineral quality. Finish: Long-lasting notes of clove, mint, and peppercorn."}, {"product_id": "532c17f3-72e0-4682-a407-004e3057fedf", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-aroostook-kentucky-grown-straight-malted-rye/", "reviewer": "New Riff", "text": "Nose: Opens with thick-cut fruit and vanilla confection, big and broad, quickly develops rye spices. Water turns it drier, husky, with the fruits again, and menthol. Palate: Medium-full bodied, with dark fruits and grassy cereal rye. Fin details of mint clove red fruit skin. Finish: Details of mint, clove, red fruit skin."}, {"product_id": "2ae97597-1f08-4517-b9ef-72b52d9f519e", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-backsetter-bourbon/", "reviewer": "New Riff", "text": "Nose: Rich oak at the forefront, before a smokiness develops alongside typical confection. It opens considerably with water, yielding a broad field of grain, roasty-nutty confection and rye spice amid a smoky, smoldering backdrop. Palate: Remarkably soft-textured at entry, with peat more immediate than in the nose. Juicy and zesty, it quickly develops a spicy rye top note at midpalate joined by smoke, oak, sweet corn and grassy rye. Finish: Smoky peat and a peppery-clove rye note."}, {"product_id": "a6f196a7-df1c-483c-8396-2921e3eacb35", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-backsetter-rye/", "reviewer": "New Riff", "text": "Nose: Considerable peat at the front, hinting at fruit and grassy rye. A splash of water detonates into a profound bouquet, as the peat retreats into stylish layers beneath a soaring top note of grassy rye and subtle cinnamon spice. Palate: Medium-to full-bodied, rounded and chewy, again with quite a bit of peat, but it is lovely peat at that, in fact absolutely gorgeous that Islay would be proud of. A midpalate of sugared fruit and cinnamon-allspice heads to a finish of wafting smoke, stylishly dovetailed with the rye spice (Thai long black pepper, mineral, grain of paradise). Finish: A midpalate of sugared fruit and cinnamon-allspice heads to a finish of wafting smoke, stylishly dovetailed with the rye spice (Thai long black pepper, mineral, grain of paradise)."}, {"product_id": "a04a16a3-61e2-4324-a084-d6b576ea542d", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-balboa-rye/", "reviewer": "New Riff", "text": "Nose: Clean ripe oak, controlled & even. With time, develops waxy/honeyed (yet not sweet) fruits. Water yields colorful (black-blue-red skinned) rye fruits and spice. Palate: Rounded and full-bodied, midpalate of spiced fruit compote. Finish: Very long and simply gorgeous, as the fruits are subtly shaded with many spices (clove, wintergreen, nutmeg)."}, {"product_id": "ce60323d-9eb3-4385-b869-0f1858ebe6e0", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-blue-clarage-bourbon/", "reviewer": "New Riff", "text": "Nose: Subtle spices of clove, faint root beer/sarsaparilla, caramelized citrus; and indeed a whiff of blue corn tortilla. Palate: Long finish is savory and juicy. Finish: Dry but rich finish."}, {"product_id": "89bd2f53-c78e-4ecd-984e-36487e071973", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-bottled-in-bond-bourbon/", "reviewer": "New Riff", "text": "Nose: Butterscotch rounding into fresh oak, with hints of vanilla and rye spice. Palate: Broad, fullsome mouthfeel, leading to a sweeter vanilla accent, before a gathering of rye spices (clove, cinnamon, mint, dark berry) into the finish. Finish: Long, rye-led finish, with brambly red-black fruits amid white pepper and clove."}, {"product_id": "349e28f8-8897-46a1-bd69-9aa36523ab5a", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-headliner-2026/", "reviewer": "New Riff", "text": "Nose: Rich oak layered with dark fruits and pine, followed by familiar New Riff clove, black pepper, and warm baking spice. Palate: Rich and balanced, opening with fig, raisin, and honeyed currants before deep oak and dark spice gather across the midpalate. Finish: Long, resinous, and dry, with lingering oak tannin, piney, black pepper, and a final echo of dark fruit."}, {"product_id": "fe7c5c85-37dc-4de7-a579-774850f6b5ff", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-maltster-bourbon-with-crystal-malt-and-malted-rye/", "reviewer": "New Riff", "text": "Nose: So much toasty, husky, toffee, quite forward and expressive, lovely emergent rye spice, cocoa nib, also rye notes of faint menthol, faint red fruits-dang, it is complicated! It relaxes with a splash of water, with more core maltiness, creamier toffee/dulce de leche/cocoa. Palate: Drier than the nose might suggest, medium-full bodied, all that husky detail again, gentle rye spices leading up to the finish. Finish: Big rye flourish finish with gentle but insistent clove, pink peppercorn, also cacoa husk."}, {"product_id": "c34cc44c-6443-4c4e-b3aa-2af7f0cda076", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-maltster-bourbon-with-malted-rye/", "reviewer": "New Riff", "text": "Nose: Cherry, leather, mint, and vanilla. Palate: Cherry, bubble gum, cinnamon, mint, and oak. Finish: Warm, medium-length with lingering cinnamon, mint, and cherry cough syrup."}, {"product_id": "56f59287-f3bc-4a51-9bc0-3659a82b48bc", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-sherry-finish-malted-rye/", "reviewer": "New Riff", "text": "Nose: Slow development of dark fruits, buttery sherry oak, walnut skin, lifted rye spice above it all with a touch of vanilla; splash of water yields multiple fruit tones. Palate: Full-bodied and broad; savory, surprisingly dry entry leads to sappy sherry backed with malty grain; well-integrated between sherry oak and grain character; although it's wickedly friendly straight up, you can add water to emphasize sherry notes, or less water for more rye. Finish: Late burst of brightening spices (clove, slight menthol, wood spice) with multicolored (blue!) fruit skin."}, {"product_id": "3899d65d-e336-4dc6-bafb-8691691f9126", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-silver-grove-bourbon-2026/", "reviewer": "New Riff", "text": "Nose: Bright apple blossom and orchard fruits, layered with subtle hints of apple brandy and baked apple. Palate: Medium-bodied and smooth, with flavors of apple fritter and candy apple leading into a subtle baking spice. Finish: Lingering notes of pecan and caramelized apple, leaving a warm, orchard-inspired finish."}, {"product_id": "a1907fd1-2a26-43c5-b82d-cd68fb73fa09", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/new-riff-silver-grove-rye-2026/", "reviewer": "New Riff", "text": "Nose: Candied orange with clove and cinnamon, bright and citrusy with warming spice accents. Palate: Creamy and layered, with clove studded orange, dark berries, and hints of toffee. Finish: Rich and warm, with oatmeal raisin and cookie dough notes lingering on the finish."}, {"product_id": "20c175b9-7940-4b5e-b283-60c96b000001", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/olnew-riff-bourbon/", "reviewer": "New Riff", "text": "Nose: Sweet wood spice with powdered sugar, a hint of minerality and trailing orange zest. Palate: Juicy and bright stone fruit up front, malt sweetness, then pink peppercorns and a touch of cedar. Finish: Long but pleasant spice and a return of the minerality."}, {"product_id": "091230a7-287f-4818-a913-99d16d5a7597", "source": "newriffdistilling.com", "source_url": "https://newriffdistilling.com/spirits/olnew-riff-rye/", "reviewer": "New Riff", "text": "Nose: Fresh oak, muddled sweet mint with a touch of citrus, lightly roasted coffee. Palate: Spicier oak, macerated darker fruits and berries. Finish: Full, but rounded spiciness of clove and nutmeg."}, {"product_id": "c5f3fb3c-add6-46d6-b611-afd2a759ab0a", "source": "oldelk.com", "source_url": "https://www.oldelk.com/lineup", "reviewer": "Old Elk", "text": "Aroma: Sweet vanilla + caramel. Clove spice, slight maple and nutty almond. Taste: Maple + chocolate. Almond, raw bran, deep wood and coconut. Finish: Smooth + coating. A lasting flavor with a rich finish."}, {"product_id": "a176c965-43ab-462e-b124-02c525320b6c", "source": "oldelk.com", "source_url": "https://www.oldelk.com/lineup", "reviewer": "Old Elk", "text": "Aroma: Soft + honey + fruity. Cherry, vanilla and oak. Taste: Warm + peach + dried fig. Vanilla, oak, yeasty notes and cedar. Finish: Warm + smooth. Lingering vanilla, oak and gentle baking spice."}, {"product_id": "a1b7be66-f761-497b-a0fd-fca5b40b7594", "source": "oldelk.com", "source_url": "https://www.oldelk.com/10-year-lineup", "reviewer": "Old Elk", "text": "Aroma: Rich oak + fig jam. Almond paste, cocoa powder and subtle honeycomb. Taste: Bright fruits + caramel. Oak sweetness and vanilla. Finish: Vanilla oak + stonefruit. Confectioner sugar with a smooth vanilla oak finish."}, {"product_id": "bbb1a0f0-731c-4153-9ab6-fd2097322661", "source": "oldelk.com", "source_url": "https://www.oldelk.com/10-year-lineup", "reviewer": "Old Elk", "text": "Aroma: Brown sugar + French vanilla. Toasted hay and caramel cream. Taste: Chocolate pastries. Brown sugar and vanilla custard. Finish: Warming + sweet oak. Vanilla cream with a lingering sweetness."}, {"product_id": "42060b8d-39f3-4d79-89a9-5da2f1e9bc05", "source": "oldelk.com", "source_url": "https://www.oldelk.com/10-year-lineup", "reviewer": "Old Elk", "text": "Aroma: Toasted oak + baking spices. Stewed apples and brown sugar. Taste: Peaches + apricots. Brown sugar, sweet cream and cinnamon. Finish: Baking spices + toasted bread. Sweet oak with a warm, lingering finish."}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "f1b88492-ae8a-46bf-9a4e-9cc85f3ef45f", "source": "oldelk.com", "source_url": "https://www.oldelk.com/cask-finish-series", "reviewer": "Old Elk", "text": "Aroma: Oak + sweet honey. Warm oak with a rich honey sweetness. Taste: Ripe fruit + red berry. Deep rich fruit, spice and cocoa. Finish: Candied sweetness + spice. Lingering sweetness with warming spice."}, {"product_id": "a522a3d4-3856-4bd6-bb42-10cd3998c489", "source": "oldelk.com", "source_url": "https://www.oldelk.com/cask-finish-series", "reviewer": "Old Elk", "text": "Aroma: Graham cracker + honeycomb. Cedar and cherry. Taste: Almond + pomegranate. Chocolate and spice. Finish: Rich + layered. Built to stand up to a cigar or work as a nightcap."}, {"product_id": "4631b067-f3bb-4c55-965c-023f215f16f0", "source": "oldelk.com", "source_url": "https://www.oldelk.com/folds-of-honor-american-whiskey", "reviewer": "Old Elk", "text": "Aroma: Caramel + vanilla. Taste: Toasted grain + warm spice. Finish: Long + Delicately sweet."}, {"product_id": "7045ea4b-4e38-4d02-9bcf-0adb51ae9110", "source": "oregonspiritdistillers.com", "source_url": "https://oregonspiritdistillers.com/straight-american-bourbon-whiskey/", "reviewer": "Oregon Spirit", "text": "Aroma: Caramel apple sweetness, floral, earthy nuttiness with light smoke and cool mint. Palate: Juicy apple, baked vanilla, wisps of smoke, hints of rye spice. Finish: Soft heat with hints of warm rye spice and lingering smoke. Mouthfeel: Warming sweetness, fresh spice."}, {"product_id": "ab2b1c47-8a4a-4d70-b9b2-96483a728bb0", "source": "oregonspiritdistillers.com", "source_url": "https://oregonspiritdistillers.com/straight-american-7-year-bourbon-cask-strength/", "reviewer": "Oregon Spirit", "text": "Aroma: Pie crust, brown sugar, rich wood aromas, stewed apples, dried hay. Palate: Caramel, golden honey, hints of apples, roasted nuts, buttered pastries, light smoke, tobacco leaf. Finish: Deep lingering finishing hug - no spikes - fading into vanilla cake frosting and smoky tart apple."}, {"product_id": "afddac4e-8a95-42dd-945f-d10bc4f009e7", "source": "oregonspiritdistillers.com", "source_url": "https://oregonspiritdistillers.com/straight-american-rye-whiskey/", "reviewer": "Oregon Spirit", "text": "Aroma: Bright floral and crisp apple balanced by herbal mint and spice. Palate: Apple carries through to meet notes of vanilla, nut and eucalyptus. Finish: Pleasant and steady with lingering spice. Mouthfeel: Fresh and light effervescence."}, {"product_id": "23bcdaec-e3dc-4e19-8761-d73e5a29ffb5", "source": "oregonspiritdistillers.com", "source_url": "https://oregonspiritdistillers.com/straight-american-wheat-whiskey/", "reviewer": "Oregon Spirit", "text": "Aroma: Light sweet mint, jammy fruit, faint hay and vanilla. Palate: Fresh bright vanilla sweetness, hints of mint, pronounced but soft rye spice. Finish: Smooth vanilla, soft spice warmth. Mouthfeel: Light and fresh."}, {"product_id": "3b824cd4-9cdd-4f1e-9175-ae4b57e8ede9", "source": "oregonspiritdistillers.com", "source_url": "https://oregonspiritdistillers.com/straight-american-malt-whiskey/", "reviewer": "Oregon Spirit", "text": "Aroma: Citrus, Vanilla. Palate: Fruity Citrus, Nut, Vanilla, Caramel, Oak. Finish: Lingering smoke. Mouthfeel: Soft and warm."}, {"product_id": "76b410fb-17e4-4cee-a8f5-5e0716e27d73", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/barrel-strength-7-year", "reviewer": "Penelope", "text": "Aroma: Pecans, dried apricot, and hints of vanilla. Palate: Carmel, toffee, leather and pecans with a hint of orange zest. Finish: White pepper, cinnamon, and brown sugar with lingering caramel."}, {"product_id": "61fc240e-2462-45fd-bd7c-0e48dbead67b", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/cigar-sessions-chapter-02", "reviewer": "Penelope", "text": "Aroma: Toasted oak, dark caramel, leather, baking spice. Palate: Charred brown sugar, sweet corn, coca, creamy malt. Finish: Dark chocolate, seasoned oak, warm spice, lingering sweetness."}, {"product_id": "61133a96-567d-41c1-925e-d81d9e166a2d", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/havana", "reviewer": "Penelope", "text": "Aroma: Molasses, banana bread, and rich maple. Palate: Robust caramel corn, charred oak, and candied pecans. Finish: Lingering vanilla, brown sugar, and syrup with hints of mellow tobacco and spice."}, {"product_id": "48670533-9230-4409-af07-a17424556c78", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/kentucky-straight-bourbon", "reviewer": "Penelope", "text": "Aroma: Butterscotch, vanilla bean, candied orange, toasted sugar. Palate: Brown Sugar, honeyed corn, cinnamon, creamy mint. Finish: Caramel, charred oak, dark chocolate, warm spice."}, {"product_id": "79858a29-286f-4999-8ece-f6be9fd7d086", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/omega", "reviewer": "Penelope", "text": "Aroma: Warm vanilla, honey, toffee, and allspice. Palate: Brown sugar, dark fruit, leather, and cocoa. Finish: Sweet spice, cinnamon gum, and buttery-sweet nougat."}, {"product_id": "22d33ecd-4c91-4f45-8e38-592c28f66dc8", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/penelope-four-grain-straight-bourbon", "reviewer": "Penelope", "text": "Aroma: Balanced corn sweetness, caramel, light oak, syrup, dynamic aroma profile with slight savory notes. Palate: Fruit, syrup, candied sweetness, and a savory vanilla note with slight berry and citrus. Finish: Slight buttercream (icing) and corn bread finish with a lingering vanilla spice."}, {"product_id": "633eb6b3-3d41-48a6-ba10-daa2e8d6012a", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/riviera", "reviewer": "Penelope", "text": "Aroma: Candied fruit and floral herbal notes. Palate: Sweet vanilla, angel food, and strawberry. Finish: Rich leather, ripe berry,and slight spice."}, {"product_id": "e568712e-2a8b-404f-8fe1-e4936613449d", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/serena-lily", "reviewer": "Penelope", "text": "Aroma: Caramel, vanilla, apricot, and red apple. Palate: Caramel, vanilla, toasted grain, and sweet corn. Finish: Lingering vanilla, touch of oak, and light baking spice."}, {"product_id": "a7450c75-891b-45be-977e-7831b6e3f313", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/straight-rye-whiskey", "reviewer": "Penelope", "text": "Aroma: Bright spearmint citrus zest, layered with baking spice and light toasted oak. Palate: Rye spice, cracked pepper, caramelized sugar, cool herbal mint and subtle citrus. Finish: Lingering spice, almond, polished oak and mint-caramel fade."}, {"product_id": "9ce3fa3d-1867-405e-810a-7270145ab41c", "source": "shop.penelopebourbon.com", "source_url": "https://shop.penelopebourbon.com/products/wheated", "reviewer": "Penelope", "text": "Aroma: Light oak, sweet corn, apple, and pear. Palate: Vanilla, honey, caramel apple, and hint of orange zest. Finish: Lingering brown sugar, toasted oak, and touch of cinnamon spice."}, {"product_id": "ebbb84d9-ac2d-4822-afcc-a183b8f2ebc2", "source": "pursuitspirits.com", "source_url": "https://pursuitspirits.com/united-bourbon/", "reviewer": "Pursuit United", "text": "Nose: Sweet fried dough and kettle corn aromas are layered with warm mulling spices. Taste: The palate offers almond croissant, baked apricot, and bright stone fruit notes. Finish: A warm finish presents cinnamon sugar, cola fizz, and a subtle black pepper spice."}, {"product_id": "c3cf2a6f-1b0f-45bb-9d27-f720313dc1e1", "source": "pursuitspirits.com", "source_url": "https://pursuitspirits.com/united-rye/", "reviewer": "Pursuit United", "text": "Nose: Bright vanilla lemon cake and citrus herbal tea aromas are accented by exotic cardamom. Taste: A comforting sweetness of brown sugar and fresh pastries is lifted by tangy lemon frosting. Finish: The gentle warmth concludes with ginger candy, baking spices, and soothing chamomile tea."}, {"product_id": "d584960d-d819-4904-a004-e95f371d0af3", "source": "pursuitspirits.com", "source_url": "https://pursuitspirits.com/double-oak-bourbon/", "reviewer": "Pursuit United", "text": "Nose: Aromas of rich butterscotch and toffee, complemented by the sweet scent of toasted marshmallows. Taste: Smooth butterscotch flavors dominate, balanced by notes of luscious vanilla custard. Finish: Warm and lingering. Cinnamon-spiced baked pears, followed by hints of toasted oak."}, {"product_id": "edcb5191-cd04-4423-931f-76590e2f2e82", "source": "pursuitspirits.com", "source_url": "https://pursuitspirits.com/double-oak-rye/", "reviewer": "Pursuit United", "text": "Nose: Opens with the aroma of fresh-baked cherry pie. Followed by bright notes of cranberry, while spices of cardamom and nutmeg add depth and complexity. Taste: Buttered brown sugar crumbles, evoking memories of a fruit crisp dessert. Balanced by the tartness of fresh cherries. A rich berry medley jam flavor rounds out the taste. Finish: Cherry pipe tobacco lends a sophisticated edge. Followed by hints of charred oak, giving it an old whiskey character providing a gentle warmth that lingers on the palate."}, {"product_id": "be562ccc-3c56-4495-aea9-d578bd0747b2", "source": "pursuitspirits.com", "source_url": "https://pursuitspirits.com/twice-toasted-bourbon/", "reviewer": "Pursuit United", "text": "Nose: An initial waft is met with a flamed orange peel followed by dusted dark chocolate roasted nuts. Taste: The chocolate notes continue with a hazelnut spread along with cherry cola on the palate. Finish: Familiar notes of toasted oak, cloves, and black pepper are prominent on the finish."}, {"product_id": "d266e128-e4ff-4bbf-ba7d-726cd21a88e0", "source": "pursuitspirits.com", "source_url": "https://pursuitspirits.com/cognac-cask-rye/", "reviewer": "Pursuit United", "text": "Nose: Fried dough, cranapple, roasted dates, and candied ginger. Taste: Baked apricots, toasted bread pudding, black walnuts, and date syrup. Finish: Jasmine tea, orange zest, sweet paprika, and charred oak."}, {"product_id": "dd0d2c24-f352-483d-a27a-d4684857c24a", "source": "rabbitholedistillery.com", "source_url": "https://www.rabbitholedistillery.com/products/adourra-founders", "reviewer": "Rabbit Hole", "text": "Aroma: Tobacco, dark cigar leaf, earthy, mineral, dry, some sweet floral note, cherry in the background, soft fruit notes. Palate: Oak, mild fruitiness, light caramel, high spice, dryness, black pepper, barrel notes, wood characters, sweetness present on the back end of palate, leather, tannins, dark fruit, cherry, custard, earthy, old wood spice, subtle wood sugars. Finish: Smoke, smooth, turns sweeter, earthiness, very long finish, dark fruit, cherry, stone fruit, caramel, long finish, smokey notes, oak, black pepper."}, {"product_id": "49eb4594-0bd5-44a5-b720-f0e550485a0d", "source": "rabbitholedistillery.com", "source_url": "https://www.rabbitholedistillery.com/products/heretofore-1-375-french-oak", "reviewer": "Rabbit Hole", "text": "Aroma: Custard, Mint, Toasted Hazelnut, Honey, and Peach. Palate: Oak, Banana, Black Pepper, Blackcurrant, Dried Fruit, and Caramel. Finish: Wood Heavy, Tobacco, and Aninse."}, {"product_id": "bc66c6a3-bf36-4adb-89e0-727e591caaeb", "source": "rabbitholedistillery.com", "source_url": "https://www.rabbitholedistillery.com/products/rabelo-1-375", "reviewer": "Rabbit Hole", "text": "Aroma: Chocolate, cherry, and caramel awaken the palate, followed by subtle but intriguing scents of vanilla, toasted nuts, banana and floral notes. Palate: Baking spices and fruits against a backdrop of sweet whiskey and wine flavors. Finish: The flavors fade into a light finish grounded by hints of port chocolate."}, {"product_id": "fabd4a96-d848-4ec5-a105-30c6d03bf0a8", "source": "rabbitholedistillery.com", "source_url": "https://www.rabbitholedistillery.com/products/velrade-375ml", "reviewer": "Rabbit Hole", "text": "Nose: On the nose, you'll find notes of dark cherry, raisins, and roasted almonds, layered with butterscotch, vanilla, and caramel to round out the aroma. Taste: On the palate, black plum, dried apricots, and molasses intertwine with toasted oak, cinnamon, and nutmeg, while warm sherry notes add depth and richness. Finish: Fig, clove, tobacco, and roasted walnuts emerge, complemented by cardamom, allspice, and a subtle hint of smokiness that lingers."}, {"product_id": "ea582e73-dfe2-44e0-9604-52a9a5803776", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/bonded-single-barrel-bourbon/", "reviewer": "Redemption", "text": "Notes: Oak, Vanilla, Crème Brûlée Aroma: Inviting aromas of vanilla and worn leather, layered with bright raspberry and subtle oak. Taste: A bold foundation of vanilla and toasted oak unfolds into rich crème brûlée, sweet corn, and warm baking spices, balanced by deep caramel richness. Aftertaste: Long and lingering, with notes of spice and oak that remain well beyond the final sip."}, {"product_id": "007b1808-ef07-4c81-b5e7-f44575ca9548", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/cognac-cask-finish/", "reviewer": "Redemption", "text": "Notes: Hibiscus, Stone Fruit, Baking Spices Aroma: Juicy floral notes of hibiscus, concord grape, and the warmth of clove and allspice. Taste: Dark stone fruits (plum, peach preserves), spiced poached pear, with a layered tannin complexity from the French oak. Aftertaste: Warming, long finish of buttered pecan, praline, baking spice."}, {"product_id": "f7657e4a-8cf3-4e1a-9215-a02017dab564", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/9-years-aged-barrel-proof-bourbon/", "reviewer": "Redemption", "text": "Notes: Vanilla, Oak, Toffee Aroma: Rich, aged oak, and smooth leather, balanced by a subtle sweetness of corn. Taste: Immediate notes of oak, cherry, and vanilla evolving into deeper layers of leather and toffee. Aftertaste: Medium in length, a satisfying blend of toffee and oak."}, {"product_id": "70b96d8f-ee18-4f2b-888e-9092ffccd2d5", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/10-year-barrel-proof-high-rye-bourbon/", "reviewer": "Redemption", "text": "Notes: Toffee, Honey, Roasted Nuts Aroma: Rich vanilla oak with hints of aged balsamic and violets Taste: Toffee, honey and roasted nut flavors dominate, layered atop a spicy rye backbone Aftertaste: Moderately drying with rich allspice and dill base notes"}, {"product_id": "75932517-200c-44dc-9079-7454fdd52265", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/10-year-barrel-proof-rye/", "reviewer": "Redemption", "text": "Notes: Vanilla, Oak, Jasmine Aroma: Rich aromas of oak and leather, balanced by delicate hints of vanilla. Taste: Floral with hints of jasmine and honeysuckle followed by layers of vanilla, caramel and baking spices. Aftertaste: A medium-long finish, notes of caramel and warm baking spices that linger on the palate."}, {"product_id": "b5ac6798-4fa8-48b2-a80b-aadd5121a3ec", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/18-year-old-bourbon/", "reviewer": "Redemption", "text": "Notes: Vanilla, Oak, Mint, Cinnamon Aroma: Immediate notes of warm oak followed by cherry jam, cinnamon, and a hint of mint Taste: Vanilla and cherry with oak and a touch of sweet corn brought together with ribbons of vanilla and leather Aftertaste: Long with oak and vanilla and a hint of cherry"}, {"product_id": "60cfaac8-ea87-4ac5-ae22-ac8c47c2ab68", "source": "redemptionwhiskey.com", "source_url": "https://www.redemptionwhiskey.com/whiskeys/18-year-old-rye/", "reviewer": "Redemption", "text": "Notes: Dark Chocolate, Citrus Aroma: Cedar, dark chocolate, rich baking spices, baked apple, peaches, rich caramel, and maple, mingled with slight herbal notes of tarragon and sage Taste: Baked apple pie, spice, almond, maple, caramel, and orange zest Aftertaste: Pears, with a bright fruit taste brought upon by heat"}, {"product_id": "eb3ca2d6-5ff1-4b97-9ce3-8c29b806eeb9", "source": "shortbarrelbourbon.com", "source_url": "https://shortbarrelbourbon.com/products/summer-solstice", "reviewer": "Shortbarrel", "text": "The nose opens with candied orange peel, honeysuckle, apricot, and vanilla bean before giving way to flavors of fresh citrus, ripe stone fruit, wild honey, toasted oak, and baking spice. The finish is long and elegant, revealing notes of orange marmalade, white pepper, and a delicate tannic grip that lingers long after the last sip."}, {"product_id": "7f83e450-4fb3-4596-a202-7001121ffcbe", "source": "smokewagon.com", "source_url": "https://www.smokewagon.com/small-batch", "reviewer": "Smoke Wagon", "text": "Nose: Balanced oak nose with hints of fruit and dried apricots. Taste: Initial sweet notes on the front of the tongue. Well balanced mouth feel with spicy notes including white pepper on the middle and back of the tongue from the younger vintage and high rye mash bill. Good balance of sweet and oak flavors including hints of caramel (from the #4 charred barrels, caramelized wood sugar), fruit flavor and rye spice. Finishes smooth with no alcohol burn even at 100 proof."}, {"product_id": "b2b55133-ba22-4b32-8ac9-042b5dfa1510", "source": "smokewagon.com", "source_url": "https://www.smokewagon.com/straight-bourbon", "reviewer": "Smoke Wagon", "text": "Nose: honey, toasted nuts and with some oak and heat. Taste: Creamy mouthfeel with initial rich sweet notes of honey and caramel on the tip of the tongue followed by nuts, oak and pepper spice that starts on the sides of your tongue. The nuttiness and oak fade as pepper spice from the rye takes over the entirety of your pallet. Finishes with a creamy sweetness that coats followed by once again by oak and a pepper spice that lingers ."}, {"product_id": "907f7033-4105-4b73-85f0-7a8c9588de89", "source": "starlightdistillery.com", "source_url": "https://starlightdistillery.com/blackberry-whiskey/", "reviewer": "Starlight", "text": "Nose: Hints of blackberry jam, caramel and vanilla beans. Taste: Farm fresh blackberry sweetness integrated with creamy vanilla flavors followed by faint toasted oak. Finish: Sweet blackberry with notes of warm caramel and oak."}, {"product_id": "80710f81-e526-4190-b686-1b4ed433b4e9", "source": "starlightdistillery.com", "source_url": "https://starlightdistillery.com/bourbons/10-year-reserve-bourbon-whiskey/", "reviewer": "Starlight", "text": "Nose: Dark Caramel, toasted vanilla, charred oak, and ripe orchard fruit with warm baking spice. Taste: Rich toffee, baked stone fruit, dark honey, and seasoned oak with remarkable depth and balance. Finish: Long, elegant, and powerfully structured with lingering oak spice, caramelized sugar, and velvety warmth."}, {"product_id": "8bfd765e-eecd-4d11-a500-c2212c245783", "source": "starlightdistillery.com", "source_url": "https://starlightdistillery.com/bourbons/bottled-in-bond-bourbon-whiskey/", "reviewer": "Starlight", "text": "Nose: Rich notes of caramel, toffee, dried red fruits and toasted oak. Taste: Starts off with toasted oak and butterscotch, that softens slowly in the mid palate, with hints of melted caramel, french vanilla, toffee with red fruit notes. Finish: Long, warm and complex with a nice level of sweetness."}, {"product_id": "3332b913-330b-4eb3-93b9-67dc6d73d1bb", "source": "starlightdistillery.com", "source_url": "https://starlightdistillery.com/flavored/peach-whiskey/", "reviewer": "Starlight", "text": "Nose: Fresh peaches with layers of sweet tangerine and nectarine. Taste: Sweet peaches integrated with creamy vanilla flavors married with the intensity of the whiskey. Finish: Farm fresh peach sweetness with notes of stone fruits followed by light caramel and faint vanilla."}, {"product_id": "9b9bc38e-f9b0-4fc0-bc83-77870f85fdfb", "source": "starlightdistillery.com", "source_url": "https://starlightdistillery.com/ryes/double-oak-old-rickhouse-rye-whiskey/", "reviewer": "Starlight", "text": "Nose: Rich notes of caramel, citrus and toasted oak. Taste: Starts off with citrus, butterscotch candy and caramel that softens in the mid palate, with hints of french vanilla, orange peels with sweet toasted oak. Finish: Long, warm with rich baking spices."}, {"product_id": "57ba38cf-52f0-4058-8003-b06d9793d638", "source": "stellum.com", "source_url": "https://www.stellum.com/rye", "reviewer": "Stellum Spirits", "text": "Nose: Stewed apples, peaches, and pears dominate the initial nose, along with an undertone of baking spices. Nutmeg and clove provide a counterbalance to the sweet fruits, while a light mint and licorice note bring further depth to the aroma. Palate: Aniseed, cardamom, and coriander wake up your palate with an intense spice punch. Notes of lemon peel and tangerine coming from the rye grain provide a nice citrus component to the overall spiciness. As the whiskey breathes in the glass, fresh green apples and spearmint arise, which offers just enough of a sweet component to engage all your taste buds. Finish: Star anise, white pepper, and mint linger on the palate before fading into a honey-sweetened jasmine green tea."}, {"product_id": "e8c979a2-81ea-4a5a-8cf1-fc72e666272a", "source": "stellum.com", "source_url": "https://www.stellum.com/huntersmoon", "reviewer": "Stellum Spirits", "text": "Nose: Very warm, rounded vanilla and butterscotch aromas initially, giving way to honeysuckle and ripened mango. Palate: Bright cinnamon at first, leading into flamed orange peel, then savory, earthy notes of black plum and petrichor. Finish: Sweet and upbeat medium finish that tapers off gracefully."}, {"product_id": "95f620b2-e269-4dc7-ab60-a4a45ef40c79", "source": "stillaustin.com", "source_url": "https://www.stillaustin.com/spirits/straight-bourbon-whiskey", "reviewer": "Still Austin Whiskey Co.", "text": "Nose: Pineapple, toasted coconut, s'mores. Palate: Cinnamon, brown butter, almonds. Finish: Tropical fruit, toffee, baking spices."}, {"product_id": "40729f55-a2d1-46aa-8484-bbefe0178b6a", "source": "stillaustin.com", "source_url": "https://www.stillaustin.com/spirits/the-artist-straight-rye-whiskey", "reviewer": "Still Austin Whiskey Co.", "text": "Nose: Honey, cherries, fig, cloves, coffee. Palate: Chocolate, apricot, sandalwood, ginger, caramel. Finish: Rye spice, nutmeg, clove, cinnamon, molasses, orange zest."}, {"product_id": "ae1f07c8-6531-4d96-874d-b7768587b701", "source": "stillaustin.com", "source_url": "https://www.stillaustin.com/spirits/cask-strength-bourbon", "reviewer": "Still Austin Whiskey Co.", "text": "Nose: Brandied cherries, muddled mint, cinnamon toast. Palate: Grilled peaches, butterscotch pecan pie, dark brown sugar. Finish: Rye spice, nutmeg, clove."}, {"product_id": "9a99f669-bf6f-496e-b980-3c31a6cc0dd2", "source": "stillaustin.com", "source_url": "https://www.stillaustin.com/spirits/cask-strength-rye-whiskey", "reviewer": "Still Austin Whiskey Co.", "text": "Nose: Cherry cobbler with a buttery cinnamon crust, candied ginger and lemon peels, apricot streusel coffee cake. Palate: Grilled peaches with mint ice cream, apple and marzipan dumplings, gingerbread cookies with lemon zest. Finish: Baking spices in brown butter, muddled cherries and mint leaves."}, {"product_id": "221f5a4d-6c29-44f6-b6d0-a1f867225b43", "source": "lexingtonbrewingco.com", "source_url": "https://lexingtonbrewingco.com/whiskey-spirits/town-branch/town-branch-true-cask-kentucky-straight-bourbon-whiskey", "reviewer": "Town Branch", "text": "The result is a traditionally rich flavor of sweet corn and cinnamon, layered with peach, cherry, vanilla, and caramel, and rounded by a bold cask-strength oak finish."}, {"product_id": "57136c7d-08db-4aa9-89ff-be67968021dc", "source": "lexingtonbrewingco.com", "source_url": "https://lexingtonbrewingco.com/whiskey-spirits/town-branch/town-branch-16yr-bottled-in-bond-kentucky-single-malt-whiskey", "reviewer": "Town Branch", "text": "This light gold spirit offers aromas of marzipan, cinnamon oatmeal, dried plums, ripe green apple, citrus, spice, leather, honey and almonds. The palate unfolds with notes of baking spice, butter cream frosting, coconut custard, black cherry, grapefruit and cinnamon, finishing with sweet mature oak, orange peel, spice and vanilla."}, {"product_id": "73f94921-67ba-49f2-928a-03971ebd6af0", "source": "twosoulsspirits.com", "source_url": "https://twosoulsspirits.com/products/j-henry-sons-7-year-rum-finished-bourbon", "reviewer": "Two Souls Spirits", "text": "Dry roasted peanuts, burnt brown sugar, fresh corn cakes, dried tropical fruit, and notes of leather and chewy oak tannins on the finish"}, {"product_id": "55590937-6c83-4768-8a4c-48d47fd37111", "source": "twosoulsspirits.com", "source_url": "https://twosoulsspirits.com/products/j-henry-sons-7-year-rum-cask-rye", "reviewer": "Two Souls Spirits", "text": "Warm cinnamon spice, clove, green apple, molasses, French vanilla, and burnt sugar with lingering mint"}, {"product_id": "24a85f7f-7fa4-48c6-8c65-dcc57036bb38", "source": "unclenearest.com", "source_url": "https://unclenearest.com/straight-rye-whiskey/", "reviewer": "Uncle Nearest", "text": "Nose: Bold and decadent with notes of praline, nutmeg and white pepper. Palate: Brimming with light vanilla cream, caramelized sugar and the unmistakable spice of rye. Finish: Long, rich and well-balanced."}, {"product_id": "6c1fb8f9-3eba-4cec-8753-256b2c6bf468", "source": "whistlepigwhiskey.com", "source_url": "https://www.whistlepigwhiskey.com/whiskeys/beyond-bonded-bourbon", "reviewer": "WhistlePig", "text": "Nose: Caramel corn partnered with oak notes. Palate: Maple and vanilla with a creamy mouth feel. Finish: Herbal tea with a hint of honey."}, {"product_id": "358566a8-6249-40b3-bc20-f4d7bce4c2fc", "source": "widowjane.com", "source_url": "https://widowjane.com/whiskey/apple-wood-aged-rye/", "reviewer": "Widow Jane", "text": "Aroma: Apple Blossom, Applewood Smoke, Spice. Taste: Baked Apple, Orange Peel. Finish: Rye, Dried Apple, Blood Orange."}, {"product_id": "1ca9fa7a-ee48-42cb-bc93-93cbf47b315b", "source": "widowjane.com", "source_url": "https://widowjane.com/whiskey/borough-blend/", "reviewer": "Widow Jane", "text": "The floral notes in Borough Blend push the fruit into new territories, and the salinity amplifies the nuttiness, warm spice, and dark coffee. Aroma: Cinnamon raisin bagel; Caramel popcorn at a baseball game; Smoke from a warm pretzel cart in Soho; Cherry blossoms in spring at the Botanical Gardens; Sweet salty scent of mandarins on Mott St. during Chinese New Year. Taste: Caramel apple dipped in peanuts; Maraschino cherries; Vanilla cherry dip in Coney Island; Coffee from that one great bodega. Finish: Peppermint stick in front of the Rockefeller tree; Black & white cookie; Plum sauce from your go-to takeout spot; Chocolate egg cream at Eddie's sweet shop."}, {"product_id": "d89f92fb-60cd-4162-bc98-8d96485ec7d7", "source": "widowjane.com", "source_url": "https://widowjane.com/whiskey/paradigm-rye/", "reviewer": "Widow Jane", "text": "Aroma: Lemon Meringue Pie, Spring Flowers, Cut Grass, Lychee. Taste: Buttered Rye Toast, Mandarin Marmalade, Cedar, White Pepper. Finish: Thyme, Artichoke, Earl Grey, Sandalwood, Peach."}, {"product_id": "f17f4d0a-4f22-4d76-95fa-a5934609ac25", "source": "widowjane.com", "source_url": "https://widowjane.com/whiskey/tequila-ocho-cask-finish/", "reviewer": "Widow Jane", "text": "Aroma: Marigold, Black Tea, Dark Tòbacco, Papaya, Lime Zest. Taste: Chocolate Pecan Pie, Canela, Dried Mango, Agave Nectar, Sun Kissed Stone. Finish: Green Peppercorns, Mesquite, Roasted Agave, Cofee, Flan."}, {"product_id": "565703cb-6dbe-4fc5-9d7a-45295bedf394", "source": "russellsreserve.com", "source_url": "https://www.russellsreserve.com/our-products/single-barrel-rye/", "reviewer": "Wild Turkey", "text": "A robust rye whiskey that strikes a balance of spicy pepper, vanilla, and tobacco flavors. Aroma: Lemon, vanilla, and spicy oak with notes of orange peel and ginger. Taste: Pepper, vanilla, and tobacco flavors. Finish: Pear drops and peppercorn."}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
insert into cellar.product_reviews (product_id, source, source_url, reviewer, text)
select r.product_id, r.source, r.source_url, r.reviewer, r.text
from jsonb_to_recordset($j$[{"product_id": "2b000691-a77f-4e6f-b538-368958440b4c", "source": "russellsreserve.com", "source_url": "https://www.russellsreserve.com/our-products/single-rickhouse/", "reviewer": "Wild Turkey", "text": "Aroma: Notes of vanilla, caramel, and maple, transition to figs, dried orange peel, cola, and toasted oak. Taste: Flavors of dried fruit, cherry, and mint, followed by graham cracker, and nutmeg spice. Finish: Warm and long-lasting with notes of sweet oak and finish of molasses and hints of black pepper."}, {"product_id": "f0e47bda-e9c0-4e33-966c-b79a3b7e94b0", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/jimmys-70th-anniversary-bourbon/", "reviewer": "Wild Turkey", "text": "Best served neat or over ice, the bourbon offers rich aromas of oak, honey, cinnamon, and tobacco and a palate marked by sweet cream, butterscotch and black tea notes that transition to bitter chocolate, dark cherry and burnt sugar. Aroma: Vanilla, oak, and honey with notes of cinnamon, brown sugar, tobacco, and orange peel. Taste: Sweet cream, vanilla, butterscotch, stone fruit (dates), pecans, and black tea. Finish: Warming with notes of caramel, dark cherry with a long lingering finish of oak, burnt sugar, and bitter chocolate."}, {"product_id": "69c0571c-fc02-424b-9efc-684888d7fd7c", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/masters-keep-beacon/", "reviewer": "Wild Turkey", "text": "Beacon showcases an aroma of dark fruit and cherry, followed by honey, vanilla and cola. On the palate, it delivers layered sweetness with caramelized sugar and toffee, balanced by tea and warm spice, finishing with aged oak and soft leather. Aroma: Aromas of dark fruit and cherry, followed by honey, vanilla and cola. Palate: Sweet notes of caramelized sugar and toffee transition to tea and warm spice. Finish: Long, warm finish of aged oak and soft leather."}, {"product_id": "9b12fd07-96b2-4c87-9362-509f08614bb8", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/masters-keep-bottled-in-bond/", "reviewer": "Wild Turkey", "text": "Taste: Sweet confectionery flavors of vanilla, honey and toffee. Aroma: Toasted oak, apple and dark cherry. Finish: Dark notes of mocha, smoke and spice."}, {"product_id": "a206ea66-7847-4f77-b284-162775b8bd92", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/masters-keep-triumph/", "reviewer": "Wild Turkey", "text": "Triumph showcases a nose of vanilla, crème brûlée, and mint that transitions to apple, pear, and nutmeg. On the palate, the whiskey brings forth notes of sweet honey and spiced clove, giving way to dark chocolate, dates and spice with a finish of rich mocha-coffee and black pepper. Aroma: Aromas of vanilla, crème brûlée, and mint followed by notes of apple, pear, and nutmeg. Palate: Sweet notes of honey and clove transition to dark chocolate, dates, and spice. Finish: Soft wood notes give way to mocha-coffee, oak, and black pepper."}, {"product_id": "b857357b-408b-489f-869a-2043112544a2", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/masters-keep-voyage/", "reviewer": "Wild Turkey", "text": "Aroma: Notes of vanilla, oak, and fruit give way to molasses, rum cake, and allspice. Palate: Sweet and creamy with notes of tropical and dried fruit, caramel and aged oak. Finish: A warm and long-lasting finish with chocolate, fruit and spice."}, {"product_id": "dadfdc1f-d4f5-4038-97d2-8db5ab85b922", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/rare-breed-rye/", "reviewer": "Wild Turkey", "text": "Taste: Sweet caramel and fruit at the start that gives way to a complex flavor of wood and rye spices. Aroma: Starts sweet with caramel apple up front, followed by rich and complex layers of honey, vanilla, rye grain spice, and charred oak underneath. Finish: Smooth and drawn-out, where lingering spice flavors mingle with dried fruit and a pleasant fading warmth."}, {"product_id": "0a7f06ab-12d4-4e5f-9969-50000dc20761", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/wild-turkey-101-rye/", "reviewer": "Wild Turkey", "text": "Taste: Warm, smoky flavors of grain and spice. Aroma: Rich, balanced caramel with honey and vanilla. Finish: Long and lingering spice with hints of smoke."}, {"product_id": "64884ad8-e944-48b0-8cad-2c719e64ddc8", "source": "wildturkeybourbon.com", "source_url": "https://www.wildturkeybourbon.com/products/wild-turkey-rye/", "reviewer": "Wild Turkey", "text": "Taste: Big vanilla and spice notes burst through. Aroma: Acutely spicy, cereal-grain sweet and a touch citrusy followed by fruit and resin scents. Finish: Bold, lingering rye and spice."}, {"product_id": "97b56daa-16e2-4475-b2d0-971c5e65c071", "source": "wildernesstraildistillery.com", "source_url": "https://www.wildernesstraildistillery.com/whiskeys/wheated-bourbon/", "reviewer": "Wilderness Trail", "text": "Nose: Sweet vanilla and charred oak. Taste: Caramel and vanilla, leading to a cordial meeting of oak, cinnamon, and blood orange with a palate-coating mouthfeel. Finish: Long and sweet, with a finish of oak spices, toffee, and dark fruits."}, {"product_id": "3fb039f6-61c6-4458-8b45-10489e1dbff8", "source": "wyomingwhiskey.com", "source_url": "https://wyomingwhiskey.com/small-batch/", "reviewer": "Wyoming Whiskey", "text": "Nose: floral, with a hint of vanilla bean and caramel pudding. Palate: brown baking spices and browned butter, vanilla crème, caramel, and a hint of cinnamon. Finish: medium length finish with toffee, spice and vanilla fade."}, {"product_id": "bc289051-3277-47b0-9586-a17aedbccb47", "source": "wyomingwhiskey.com", "source_url": "https://wyomingwhiskey.com/double-cask/", "reviewer": "Wyoming Whiskey", "text": "Nose: autumnal notes of dried apricot, mission fig, and dried date. Taste: stewed prune and black raisin, with hints of candied orange peel; vanilla butter cream and toffee underneath. Finish: dark dried fruit, followed by warming brown baking spices."}, {"product_id": "50b2ade2-d5d2-4063-8bda-70d0e02d5604", "source": "wyomingwhiskey.com", "source_url": "https://wyomingwhiskey.com/outryder/", "reviewer": "Wyoming Whiskey", "text": "Nose: pumpernickel bread with melted butter, honey aromas of beeswax candles with orange blossom pollen, and warm cherry cobbler. Taste: hot chocolate, yeast biscuits drizzled with dark molasses, honeyed hay, and roasted cumin in brown butter. Finish: long and warming, with lingering flavors of maple syrup over French toast."}]$j$::jsonb) as r(product_id uuid, source text, source_url text, reviewer text, text text)
where not exists (select 1 from cellar.product_reviews e where e.product_id = r.product_id and e.source_url = r.source_url);
